/**
 * La CSP tiene que permitir los orígenes que la app realmente llama.
 *
 * Es la clase de error que no aparece en ningún test ni en el build: el
 * navegador bloquea la llamada en producción y el mensaje que ve la persona
 * apunta al lugar equivocado —"No se pudo conectar", como si fuera su wifi—.
 * Pasó el 15/09 con Firebase, que quedó afuera de `connect-src`.
 *
 * Cada origen de acá abajo está porque hay código que le habla. Si se quita esa
 * integración, se quita la línea; mientras exista, la CSP no puede olvidarla.
 */
import { describe, expect, it } from "vitest";

import nextConfig from "../../next.config";

/** Origen → quién lo llama, para que al romperse se sepa qué se apagó. */
const CONNECT_SRC = [
  ["https://identitytoolkit.googleapis.com", "Firebase: alta, ingreso y envío de correos"],
  ["https://securetoken.googleapis.com", "Firebase: renovación del ID token"],
  ["https://accounts.google.com/gsi/", "Google Identity Services: el botón"],
] as const;

async function directivas(): Promise<Map<string, string[]>> {
  const headers = await nextConfig.headers!();
  const csp = headers
    .flatMap((h) => h.headers)
    .find((h) => h.key === "Content-Security-Policy");
  if (!csp) throw new Error("no hay Content-Security-Policy configurada");

  return new Map(
    csp.value.split(";").map((d) => {
      const [nombre, ...valores] = d.trim().split(/\s+/);
      return [nombre, valores];
    }),
  );
}

describe("Content-Security-Policy", () => {
  it.each(CONNECT_SRC)("permite conectarse a %s (%s)", async (origen) => {
    const connectSrc = (await directivas()).get("connect-src") ?? [];
    expect(connectSrc).toContain(origen);
  });

  it("deja cargar los tiles de Esri que usan los mapas", async () => {
    // Estuvo bloqueado hasta el 18/09: los vuelos se dibujaban sobre gris.
    const imgSrc = (await directivas()).get("img-src") ?? [];
    expect(imgSrc).toContain("https://server.arcgisonline.com");
  });

  it("sigue cargando el script de Google Identity Services", async () => {
    const scriptSrc = (await directivas()).get("script-src") ?? [];
    expect(scriptSrc).toContain("https://accounts.google.com/gsi/client");
  });

  it("no se abre a cualquier origen para tapar un bloqueo", async () => {
    // El atajo cuando algo se bloquea es poner `*` y seguir. Que falle acá.
    const todas = await directivas();
    for (const clave of ["connect-src", "script-src", "frame-src", "default-src"]) {
      expect(todas.get(clave) ?? []).not.toContain("*");
    }
  });
});

/**
 * Las páginas que las tiendas exigen públicas tienen que abrir sin sesión.
 *
 * Apple verifica la URL de la política de privacidad y la de soporte antes de
 * aceptar el envío a revisión; si el proxy las manda al login, el envío se
 * rechaza sin que ningún test ni build lo anticipe. Este test es ese aviso.
 */
import { describe, expect, it } from "vitest";
import { NextRequest } from "next/server";

import { proxy } from "../proxy";

/** Ruta → quién exige que sea pública. */
const PUBLICAS = [
  ["/privacidad", "App Store Connect y Play: URL de política de privacidad"],
  ["/soporte", "App Store Connect: URL de soporte"],
] as const;

function pedir(pathname: string) {
  return proxy(new NextRequest(`https://app.test${pathname}`));
}

describe("proxy: rutas públicas", () => {
  for (const [ruta, motivo] of PUBLICAS) {
    it(`deja pasar ${ruta} sin sesión — ${motivo}`, () => {
      const respuesta = pedir(ruta);
      expect(respuesta.status).toBe(200);
      expect(respuesta.headers.get("location")).toBeNull();
    });
  }

  it("sigue exigiendo sesión para el resto", () => {
    const respuesta = pedir("/flights");
    expect(respuesta.status).toBeGreaterThanOrEqual(300);
    expect(respuesta.headers.get("location")).toContain("/login");
  });
});

/**
 * Las rutas de acceso no pueden caer en el estado de carga del dashboard.
 *
 * `src/app/loading.tsx` renderiza `<AppShell>` —barra lateral y encabezado del
 * tablero— y en Next eso aplica a TODA ruta que no tenga el suyo. Al navegar
 * entre `/login` y `/signup` se veía el dashboard completo por un instante,
 * con sesión o sin ella, antes de llegar a un formulario.
 *
 * Se verifica sobre los archivos porque el defecto es de estructura: no hay
 * render que lo exponga, solo la ausencia de un archivo. `/onboarding` se sumo
 * despues, por eso mismo: se llega una sola vez por cuenta y nadie lo miro
 * hasta que aparecio en una captura.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const APP = join(process.cwd(), "src", "app");

/** Rutas propias que se ven sin el marco del dashboard. */
const RUTAS = ["login", "signup", "onboarding"];

describe("estados de carga de las rutas de acceso", () => {
  it("el loading raíz sigue importando AppShell", () => {
    // Si algún día deja de hacerlo, estos tests sobran y conviene saberlo.
    const raiz = readFileSync(join(APP, "loading.tsx"), "utf8");
    expect(raiz).toMatch(/import .*AppShell.* from/);
  });

  it.each(RUTAS)("/%s tiene su propio loading", (ruta) => {
    expect(existsSync(join(APP, ruta, "loading.tsx"))).toBe(true);
  });

  it.each(RUTAS)("el loading de /%s no trae el chrome", (ruta) => {
    // Se mira el import y no la palabra: el comentario de esos archivos
    // nombra a `AppShell` justamente para explicar por qué no lo usan.
    const contenido = readFileSync(join(APP, ruta, "loading.tsx"), "utf8");
    expect(contenido).not.toMatch(/import .*AppShell.* from/);
    expect(contenido).not.toMatch(/<AppShell/);
  });
});

import { redirect } from "next/navigation";
import { getServerRole } from "@/lib/server-auth";

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const role = await getServerRole();
  if (role !== "superadmin") redirect("/");
  return <>{children}</>;
}

"use client";

import * as React from "react";
import { AppShell } from "@/components/app-shell";
import { api, type ManagedUser } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, Pencil, Trash2, ShieldOff, ShieldCheck } from "lucide-react";
import { fmtTime } from "@/lib/api";
import { useSession } from "@/components/providers/session-provider";
import { toast } from "sonner";

const ROLE_LABELS: Record<string, string> = {
  superadmin: "Superadmin",
  admin: "Admin",
  user: "Usuario",
};

const ROLE_VARIANTS: Record<string, "default" | "secondary" | "outline"> = {
  superadmin: "default",
  admin: "secondary",
  user: "outline",
};

function fmtDate(utc: string) {
  return fmtTime(utc).split(" ")[0]; // just dd/MM
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
export default function UsersPage() {
  const { user: sessionUser } = useSession();
  const me = sessionUser?.username ?? null;
  const [users, setUsers] = React.useState<ManagedUser[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState("");

  // Create dialog
  const [createOpen, setCreateOpen] = React.useState(false);
  const [newUsername, setNewUsername] = React.useState("");
  const [newPassword, setNewPassword] = React.useState("");
  const [newRole, setNewRole] = React.useState("user");
  const [creating, setCreating] = React.useState(false);

  // Edit dialog
  const [editUser, setEditUser] = React.useState<ManagedUser | null>(null);
  const [editRole, setEditRole] = React.useState("");
  const [editPassword, setEditPassword] = React.useState("");
  const [editing, setEditing] = React.useState(false);

  // Delete confirm
  const [deleteUser, setDeleteUser] = React.useState<ManagedUser | null>(null);
  const [deleting, setDeleting] = React.useState(false);

  async function loadUsers() {
    try {
      setLoading(true);
      setError("");
      setUsers(await api.listUsers());
    } catch {
      setError("No se pudieron cargar los usuarios.");
    } finally {
      setLoading(false);
    }
  }

  React.useEffect(() => {
    let active = true;
    api.listUsers()
      .then((data) => { if (active) setUsers(data); })
      .catch(() => { if (active) setError("No se pudieron cargar los usuarios."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    setCreating(true);
    try {
      await api.createUser(newUsername.trim(), newPassword, newRole);
      setCreateOpen(false);
      setNewUsername(""); setNewPassword(""); setNewRole("user");
      toast.success("Usuario creado");
      await loadUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Error al crear usuario");
    } finally {
      setCreating(false);
    }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault();
    if (!editUser) return;
    setEditing(true);
    try {
      const patch: { role?: string; password?: string } = {};
      if (editRole && editRole !== editUser.role) patch.role = editRole;
      if (editPassword.trim()) patch.password = editPassword;
      if (Object.keys(patch).length) await api.updateUser(editUser.username, patch);
      setEditUser(null); setEditPassword("");
      toast.success("Usuario actualizado");
      await loadUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Error al editar usuario");
    } finally {
      setEditing(false);
    }
  }

  async function handleToggleActive(user: ManagedUser) {
    try {
      await api.updateUser(user.username, { active: !user.active });
      toast.success(user.active ? "Usuario desactivado" : "Usuario activado");
      await loadUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "No se pudo actualizar el usuario");
    }
  }

  async function handleDelete() {
    if (!deleteUser) return;
    setDeleting(true);
    try {
      await api.deleteUser(deleteUser.username);
      setDeleteUser(null);
      toast.success("Usuario eliminado");
      await loadUsers();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Error al eliminar usuario");
    } finally {
      setDeleting(false);
    }
  }

  return (
    <AppShell title="Gestión de usuarios">
      <div className="mx-auto w-full max-w-4xl space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-semibold tracking-tight">Usuarios</h1>
            <p className="text-sm text-muted-foreground">
              Gestioná cuentas, roles y accesos al sistema.
            </p>
          </div>
          <Button onClick={() => setCreateOpen(true)} className="gap-2">
            <Plus className="size-4" />
            Nuevo usuario
          </Button>
        </div>

        {error && <p className="text-sm text-destructive">{error}</p>}

        <div className="rounded-lg border bg-card">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/30 hover:bg-muted/30">
                <TableHead>Usuario</TableHead>
                <TableHead>Rol</TableHead>
                <TableHead>Estado</TableHead>
                <TableHead className="hidden sm:table-cell">Creado</TableHead>
                <TableHead className="w-[120px] text-right">Acciones</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                Array.from({ length: 3 }).map((_, i) => (
                  <TableRow key={i}>
                    <TableCell><div className="h-4 w-24 animate-pulse rounded bg-muted" /></TableCell>
                    <TableCell><div className="h-5 w-16 animate-pulse rounded-full bg-muted" /></TableCell>
                    <TableCell><div className="h-5 w-16 animate-pulse rounded-full bg-muted" /></TableCell>
                    <TableCell className="hidden sm:table-cell"><div className="h-4 w-16 animate-pulse rounded bg-muted" /></TableCell>
                    <TableCell />
                  </TableRow>
                ))
              ) : users.map((u) => (
                <TableRow key={u.id} className={!u.active ? "opacity-50" : undefined}>
                  <TableCell className="font-mono text-sm font-medium">{u.username}</TableCell>
                  <TableCell>
                    <Badge variant={ROLE_VARIANTS[u.role] ?? "outline"}>
                      {ROLE_LABELS[u.role] ?? u.role}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant={u.active ? "outline" : "secondary"} className={u.active ? "text-risk-low border-risk-low/30" : ""}>
                      {u.active ? "Activo" : "Desactivado"}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-xs text-muted-foreground">
                    {fmtDate(u.created_at)}
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        title={u.active ? "Desactivar" : "Activar"}
                        aria-label={`${u.active ? "Desactivar" : "Activar"} a ${u.username}`}
                        disabled={u.username === me}
                        onClick={() => handleToggleActive(u)}
                      >
                        {u.active
                          ? <ShieldOff className="size-4 text-muted-foreground" />
                          : <ShieldCheck className="size-4 text-risk-low" />}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        title="Editar"
                        aria-label={`Editar a ${u.username}`}
                        disabled={u.username === me}
                        onClick={() => { setEditUser(u); setEditRole(u.role); setEditPassword(""); }}
                      >
                        <Pencil className="size-4 text-muted-foreground" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        title="Eliminar"
                        aria-label={`Eliminar a ${u.username}`}
                        disabled={u.username === me}
                        onClick={() => setDeleteUser(u)}
                      >
                        <Trash2 className="size-4 text-destructive" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        <p className="text-xs text-muted-foreground">
          {loading ? "Cargando..." : `${users.length} usuario${users.length !== 1 ? "s" : ""}`}
        </p>
      </div>

      {/* Create dialog */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Nuevo usuario</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleCreate} className="space-y-4 pt-2">
            <div className="space-y-1.5">
              <Label htmlFor="new-username">Usuario</Label>
              <Input id="new-username" value={newUsername} onChange={(e) => setNewUsername(e.target.value)} required autoFocus />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="new-password">Contraseña</Label>
              <Input id="new-password" type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} required />
            </div>
            <div className="space-y-1.5">
              <Label>Rol</Label>
              <Select value={newRole} onValueChange={(v) => v && setNewRole(v)}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="user">Usuario</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="superadmin">Superadmin</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setCreateOpen(false)}>Cancelar</Button>
              <Button type="submit" disabled={creating}>{creating ? "Creando..." : "Crear"}</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Edit dialog */}
      <Dialog open={!!editUser} onOpenChange={(o) => { if (!o) setEditUser(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Editar — {editUser?.username}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleEdit} className="space-y-4 pt-2">
            <div className="space-y-1.5">
              <Label>Rol</Label>
              <Select value={editRole} onValueChange={(v) => v && setEditRole(v)}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="user">Usuario</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="superadmin">Superadmin</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="edit-password">Nueva contraseña <span className="text-muted-foreground">(dejar vacío para no cambiar)</span></Label>
              <Input id="edit-password" type="password" value={editPassword} onChange={(e) => setEditPassword(e.target.value)} />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setEditUser(null)}>Cancelar</Button>
              <Button type="submit" disabled={editing}>{editing ? "Guardando..." : "Guardar"}</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete confirm dialog */}
      <Dialog open={!!deleteUser} onOpenChange={(o) => { if (!o) setDeleteUser(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Eliminar usuario</DialogTitle>
          </DialogHeader>
          <p className="text-sm text-muted-foreground py-2">
            ¿Seguro que querés eliminar a <span className="font-mono font-medium text-foreground">{deleteUser?.username}</span>? Esta acción no se puede deshacer.
          </p>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteUser(null)}>Cancelar</Button>
            <Button variant="destructive" onClick={handleDelete} disabled={deleting}>
              {deleting ? "Eliminando..." : "Eliminar"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </AppShell>
  );
}

import { AppShell } from "@/components/app-shell";
import { AlertasClimaView } from "@/components/viajero/alertas-clima-view";
import { api, type WeatherAlert } from "@/lib/api";

async function cargar(): Promise<WeatherAlert[]> {
  try {
    return await api.weatherAlerts("high");
  } catch {
    return [];
  }
}

export default async function AlertasPage() {
  const alertas = await cargar();
  return (
    <AppShell title="Alertas meteorológicas">
      <div className="mx-auto w-full max-w-5xl space-y-4">
        <header className="space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight">
            Alertas meteorológicas
          </h1>
          <p className="text-sm text-muted-foreground">
            Aeropuertos con mal tiempo ahora mismo, del más grave al menos.
          </p>
        </header>
        <AlertasClimaView iniciales={alertas} />
      </div>
    </AppShell>
  );
}

/**
 * El canje del token de Firebase por la sesión propia.
 *
 * Lo que este handler tiene que garantizar y no se ve leyéndolo: que el 403 de
 * "falta verificar el correo" llegue entero al navegador —es el único rechazo
 * sobre el que la persona puede hacer algo— y que el token de Firebase no
 * termine en la cookie, porque prueba quién es una vez y no lleva nuestro rol.
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { POST } from "@/app/api/auth/firebase/route";
import { AUTH_COOKIE_NAME } from "@/lib/auth-types";

const TOKEN = "encabezado.cuerpo.firma";

function pedido(body: unknown) {
  return new Request("http://localhost:3000/api/auth/firebase", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: typeof body === "string" ? body : JSON.stringify(body),
  });
}

/** Simula las dos llamadas al backend: el canje y después /auth/me. */
function backend(opciones: {
  canje: { status: number; body: unknown };
  me?: { status: number; body: unknown };
}) {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string | URL) => {
      if (String(url).endsWith("/auth/firebase")) {
        return new Response(JSON.stringify(opciones.canje.body), {
          status: opciones.canje.status,
        });
      }
      const me = opciones.me ?? { status: 200, body: {} };
      return new Response(JSON.stringify(me.body), { status: me.status });
    }),
  );
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("POST /api/auth/firebase", () => {
  it("rechaza un cuerpo que no es JSON", async () => {
    expect((await POST(pedido("esto-no-es-json"))).status).toBe(400);
  });

  it.each([{}, { id_token: "" }, { id_token: 42 }])(
    "rechaza un id_token ausente o del tipo equivocado (%j)",
    async (body) => {
      expect((await POST(pedido(body))).status).toBe(400);
    },
  );

  it("deja pasar el 403 de correo sin verificar tal cual viene", async () => {
    backend({
      canje: {
        status: 403,
        body: { detail: "Falta verificar el correo. Revisá tu casilla y volvé a intentar." },
      },
    });

    const respuesta = await POST(pedido({ id_token: TOKEN }));
    // No es un 401 genérico: quien lo recibe puede ir a su casilla y resolverlo.
    expect(respuesta.status).toBe(403);
    await expect(respuesta.json()).resolves.toMatchObject({
      detail: "Falta verificar el correo. Revisá tu casilla y volvé a intentar.",
    });
  });

  it("deja nuestro JWT en la cookie, no el token de Firebase", async () => {
    backend({
      canje: {
        status: 200,
        body: { access_token: "jwt-propio", user_type: "b2c", is_new_user: false },
      },
      me: { status: 200, body: { username: "a@b.com", role: "user" } },
    });

    const respuesta = await POST(pedido({ id_token: TOKEN }));
    expect(respuesta.status).toBe(200);
    await expect(respuesta.json()).resolves.toEqual({
      username: "a@b.com",
      role: "user",
      userType: "b2c",
      isNewUser: false,
    });

    const cookie = respuesta.cookies.get(AUTH_COOKIE_NAME);
    expect(cookie?.value).toBe("jwt-propio");
    expect(cookie?.value).not.toBe(TOKEN);
    expect(cookie?.httpOnly).toBe(true);
  });

  it("manda al onboarding a una cuenta recién creada", async () => {
    backend({
      canje: {
        status: 200,
        body: { access_token: "jwt-propio", user_type: null, is_new_user: true },
      },
      me: { status: 200, body: { username: "a@b.com", role: "user" } },
    });

    await expect(
      (await POST(pedido({ id_token: TOKEN }))).json(),
    ).resolves.toMatchObject({ userType: null, isNewUser: true });
  });

  it("manda al onboarding a quien vuelve sin haber elegido tipo de cuenta", async () => {
    backend({
      canje: {
        status: 200,
        body: { access_token: "jwt-propio", user_type: null, is_new_user: false },
      },
      me: { status: 200, body: { username: "a@b.com", role: "user" } },
    });

    await expect(
      (await POST(pedido({ id_token: TOKEN }))).json(),
    ).resolves.toMatchObject({ isNewUser: true });
  });

  it("no abre una sesión que el backend no sabe describir", async () => {
    backend({
