}

export function HourlyDelayChart({ initialData }: { initialData?: HourlyBucket[] } = {}) {
  const [data, setData] = React.useState<HourlyBucket[]>(initialData ?? []);
  const [loading, setLoading] = React.useState(!initialData);

  React.useEffect(() => {
    if (initialData) return;
    api.hourly()
      .then(setData)
      .catch(() => setData([]))
      .finally(() => setLoading(false));
  }, [initialData]);

  const chartData: ChartItem[] = data.map((b) => ({
    hour:   b.hour,
    high:   b.high_risk,
    medium: b.medium_risk ?? (b.total - b.high_risk),
    low:    b.low_risk ?? 0,
    total:  b.total,
  }));

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium">
            Vuelos por hora — ATL
          </CardTitle>
          {!loading && data.length > 0 && (
            <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
              <span className="flex items-center gap-1">
                <span className="inline-block size-2 rounded-full bg-risk-low" />
                Bajo <span className="text-[10px] opacity-60">(&lt;15%)</span>
              </span>
              <span className="flex items-center gap-1">
                <span className="inline-block size-2 rounded-full bg-risk-medium" />
                Medio <span className="text-[10px] opacity-60">(15–35%)</span>
              </span>
              <span className="flex items-center gap-1">
                <span className="inline-block size-2 rounded-full bg-risk-high" />
                Alto <span className="text-[10px] opacity-60">(&gt;35%)</span>
              </span>
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent>
        {loading ? (
          <ChartSkeleton />
        ) : data.length === 0 ? (
          <div className="flex h-[300px] items-center justify-center text-sm text-muted-foreground">
            Sin datos de predicciones para el día de hoy.
          </div>
        ) : (
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData} barSize={18} barGap={0}>
              <CartesianGrid vertical={false} strokeDasharray="3 3" />
              <XAxis
                dataKey="hour"
                tickLine={false}
                axisLine={false}
                tickMargin={8}
                fontSize={11}
              />
              <YAxis
                tickLine={false}
                axisLine={false}
                tickMargin={8}
                fontSize={11}
                width={28}
                allowDecimals={false}
              />
              <Tooltip content={<CustomTooltip />} cursor={{ fill: "var(--muted)", opacity: 0.4 }} />
              <Bar dataKey="low"    name="Bajo"  stackId="a" fill="var(--color-risk-low)"    radius={[0,0,0,0]} />
              <Bar dataKey="medium" name="Medio" stackId="a" fill="var(--color-risk-medium)" radius={[0,0,0,0]} />
              <Bar dataKey="high"   name="Alto"  stackId="a" fill="var(--color-risk-high)"   radius={[3,3,0,0]} />
            </BarChart>
          </ResponsiveContainer>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * Marco de las páginas legales públicas (privacidad, soporte).
 *
 * Son las únicas páginas del sitio que un desconocido lee de arriba a abajo sin
 * sesión: las dos tiendas exigen que abran sin login y el revisor las visita.
 * Por eso no usan `AppShell` (que dibuja la barra lateral y el menú de una
 * cuenta) sino un documento angosto, con la marca arriba y nada más alrededor.
 *
 * El contenido va como `children` con clases de texto propias: no está el
 * plugin de tipografía de Tailwind y traerlo para dos páginas no compensa.
 */

import type { ReactNode } from "react";
import Link from "next/link";

import { BrandMark } from "@/components/brand-mark";

export function LegalShell({
  title,
  updated,
  children,
}: {
  title: string;
  /** Fecha ISO de la última revisión; se muestra debajo del título. */
  updated?: string;
  children: ReactNode;
}) {
  return (
    <main className="min-h-screen bg-background px-6 py-12 text-foreground">
      <article className="mx-auto w-full max-w-2xl">
        <header className="flex flex-col items-center text-center">
          <Link href="/" aria-label="Ir al inicio">
            <BrandMark />
          </Link>
          <h1 className="mt-8 text-2xl font-semibold tracking-tight">{title}</h1>
          {updated && (
            <p className="mt-2 text-xs text-muted-foreground">
              Última actualización:{" "}
              <time dateTime={updated}>{formatearFecha(updated)}</time>
            </p>
          )}
        </header>

        <div className="mt-10 space-y-8 text-sm leading-relaxed text-foreground/90 [&_a]:underline [&_a]:underline-offset-4 [&_h2]:text-base [&_h2]:font-semibold [&_h2]:tracking-tight [&_h2]:text-foreground [&_li]:mt-1.5 [&_p+p]:mt-3 [&_ul]:mt-3 [&_ul]:list-disc [&_ul]:pl-5">
          {children}
        </div>

        <footer className="mt-12 border-t border-border pt-6 text-center text-xs text-muted-foreground">
          <Link href="/privacidad">Política de privacidad</Link>
          {" · "}
          <Link href="/soporte">Soporte</Link>
        </footer>
      </article>
    </main>
  );
}

/** "2026-09-18" → "18 de septiembre de 2026", sin depender del huso del lector. */
function formatearFecha(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  return new Intl.DateTimeFormat("es-AR", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(y, m - 1, d)));
}

