const RISK_COLOR: Record<MapTrack["risk"], string> = {
  low: "#4ade80",
  medium: "#facc15",
  high: "#f87171",
};

function planeIcon(bearing: number, risk: MapTrack["risk"], selected = false) {
  const color = RISK_COLOR[risk];
  const scale = selected ? 1.25 : 1;
  const ring = selected
    ? `<circle cx="14" cy="14" r="13" fill="${color}" fill-opacity="0.18" stroke="${color}" stroke-opacity="0.55" stroke-width="1" />`
    : "";
  const html = `
    <div class="relative" style="width:28px;height:28px;transform:rotate(${bearing}deg);transform-origin:center;">
      <svg viewBox="0 0 28 28" width="28" height="28" xmlns="http://www.w3.org/2000/svg" style="transform:scale(${scale});transform-origin:center;">
        ${ring}
        <path d="M14 2 L16.2 12.2 L26 15 L26 17 L16.2 15.6 L15.3 22 L17.8 24 L17.8 25.5 L14 24.6 L10.2 25.5 L10.2 24 L12.7 22 L11.8 15.6 L2 17 L2 15 L11.8 12.2 Z"
              fill="${color}" stroke="#0b1220" stroke-width="0.6" stroke-linejoin="round" />
      </svg>
    </div>
  `;
  return L.divIcon({
    html,
    className: "ontimeai-plane-icon",
    iconSize: [28, 28],
    iconAnchor: [14, 14],
  });
}

function airportIcon(code: string, variant: "origin" | "destination") {
  const bg = variant === "origin" ? "#60a5fa" : "#94a3b8";
  const html = `
    <div style="display:flex;flex-direction:column;align-items:center;transform:translateY(-6px);pointer-events:none;">
      <div style="font-family:ui-monospace,Menlo,monospace;font-size:10px;font-weight:700;letter-spacing:0.05em;color:${bg};text-shadow:0 1px 2px rgba(0,0,0,0.8);">${code}</div>
      <div style="width:10px;height:10px;border-radius:50%;background:${bg};box-shadow:0 0 0 2px rgba(15,23,42,0.9), 0 0 0 3px ${bg}33;margin-top:2px;"></div>
    </div>
  `;
  return L.divIcon({
    html,
    className: "ontimeai-airport-icon",
    iconSize: [32, 28],
    iconAnchor: [16, 18],
  });
}

function FitToFlights({ flights }: { flights: MapTrack[] }) {
  const map = useMap();
  React.useEffect(() => {
    if (flights.length === 0) return;
    const points: Array<[number, number]> = flights.map((f) => [f.currentLat, f.currentLng]);
    points.push([AIRPORTS.ATL.lat, AIRPORTS.ATL.lng]);
    map.fitBounds(points, { padding: [48, 48] });
  }, [flights, map]);
  return null;
}

export type FlightRadarMapProps = {
  flights?: MapTrack[];
  selectedId?: string;
  onSelect?: (id: string) => void;
  className?: string;
  height?: number | string;
  showRoutes?: boolean;
};

export function FlightRadarMap({
  flights = [],
  selectedId,
  onSelect,
  className,
  height = 520,
  showRoutes = true,
}: FlightRadarMapProps) {
  const originCoords = AIRPORTS.ATL;
  const destinations = React.useMemo(() => {
    const seen = new Set<string>();
    const list: Array<{ code: string } & LatLng> = [];
    for (const f of flights) {
      if (!seen.has(f.destination)) {
        seen.add(f.destination);
        list.push({ code: f.destination, lat: f.destLat, lng: f.destLng });
      }
    }
    return list;
  }, [flights]);

  return (
    <div
      // `isolate`: las capas de Leaflet van con z-index 400–1000 y los overlays
      // de acá con z-[400]. Sin un contexto de apilamiento propio, todo eso
      // compite en el de la raíz y le gana al menú lateral (z-50): en el
      // teléfono el mapa se dibujaba por encima del drawer abierto.
      className={cn("relative isolate overflow-hidden rounded-lg border bg-[#0b1220]", className)}
      style={{ height }}
    >
      <MapContainer
        center={[originCoords.lat, originCoords.lng]}
        zoom={4}
        minZoom={3}
        maxZoom={10}
        worldCopyJump
        zoomControl={false}
        attributionControl={false}
        style={{ height: "100%", width: "100%", background: "#0b1220" }}
      >
        {/* CARTO pasó a exigir API key y estampa una marca de agua sobre cada
            tile. Esri World Dark Gray es gratuito, sin clave y de estilo oscuro. */}
        <TileLayer
          url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}"
          maxZoom={16}
          attribution='&copy; <a href="https://www.esri.com/">Esri</a>'
        />

        <FitToFlights flights={flights} />

        {showRoutes && flights.map((f) => {
          const o = { lat: f.originLat, lng: f.originLng };
          const d = { lat: f.destLat, lng: f.destLng };
          const path = greatCirclePath(o, d, 48);
          const flown = path.slice(0, Math.max(2, Math.round(path.length * f.progress)));
          const remaining = path.slice(flown.length - 1);
          const color = RISK_COLOR[f.risk];
          return (
            <React.Fragment key={f.id}>
              <Polyline positions={remaining} pathOptions={{ color, weight: 1, opacity: 0.35, dashArray: "3 5" }} />
              <Polyline positions={flown} pathOptions={{ color, weight: 1.6, opacity: 0.85 }} />
            </React.Fragment>
          );
        })}

        <Marker
          position={[originCoords.lat, originCoords.lng]}
          icon={airportIcon("ATL", "origin")}
          interactive={false}
        />

        {destinations.map((d) => (
          <Marker
            key={d.code}
            position={[d.lat, d.lng]}
            icon={airportIcon(d.code, "destination")}
            interactive={false}
          />
        ))}

        {flights.map((f) => {
          const selected = selectedId === f.id;
          return (
            <Marker
              key={f.id}
              position={[f.currentLat, f.currentLng]}
              icon={planeIcon(f.bearing, f.risk, selected)}
              eventHandlers={{ click: () => onSelect?.(f.id) }}
            >
              <Tooltip direction="top" offset={[0, -10]} opacity={1}>
                <FlightTooltip flight={f} />
              </Tooltip>
            </Marker>
          );
        })}

        {selectedId && flights.find((f) => f.id === selectedId) ? (
          <CircleMarker
            center={[
              flights.find((f) => f.id === selectedId)!.currentLat,
              flights.find((f) => f.id === selectedId)!.currentLng,
            ]}
            radius={18}
            pathOptions={{
              color: RISK_COLOR[flights.find((f) => f.id === selectedId)!.risk],
              weight: 1,
              opacity: 0.6,
              fillOpacity: 0.05,
            }}
          />
        ) : null}
      </MapContainer>

      <MapLegend />
      <LiveBadge count={flights.length} />
      {onSelect && (
        <SelectedCard
          flight={flights.find((f) => f.id === selectedId) ?? null}
          onClose={() => onSelect?.("")}
        />
      )}
    </div>
  );
}

function FlightTooltip({ flight }: { flight: MapTrack }) {
  return (
    <div className="font-sans text-xs text-white">
      <div className="font-mono text-[11px] font-semibold">{flight.flightNumber}</div>
      <div className="text-[10px] opacity-80">{flight.origin} → {flight.destination}</div>
      <div className="mt-1 text-[10px]" style={{ color: RISK_COLOR[flight.risk] }}>
        {Math.round(flight.delayProbability * 100)}% riesgo · {
