        <span style="color:#cbd5e1;">${station.temperatureF === null ? "—" : `${station.temperatureF}°`}</span>
      </div>
    </div>
  `;
  return L.divIcon({
    html,
    className: "ontimeai-weather-icon",
    iconSize: [72, 22],
    iconAnchor: [36, 11],
  });
}

function FitToStations({ stations }: { stations: WeatherStation[] }) {
  const map = useMap();
  React.useEffect(() => {
    if (stations.length === 0) return;
    const bounds = L.latLngBounds(stations.map((s) => [s.lat, s.lng] as [number, number]));
    map.fitBounds(bounds, { padding: [48, 48] });
  }, [stations, map]);
  return null;
}

