"use client";

/**
 * AUC antes de salir contra AUC en vuelo.
 *
 * Es la comparación que decide si el sistema sirve. Predecir con el avión
 * volando es fácil: media hora después se sabe solo, y el modelo ya vio el
 * retraso de salida. El valor está en acertar **antes de que salga**, que es
 * cuando todavía se puede hacer algo.
 *
 * Que la línea de en vuelo esté por encima es lo esperado. Lo que hay que mirar
 * es cuánta distancia hay: si es mucha, el modelo depende de información que
 * llega demasiado tarde para ser útil.
 *
 * Solo se dibujan los promedios de siete días. Superponer además los valores
 * diarios de dos series deja un enredo del que no se lee ninguna de las dos.
 */

import {
  CartesianGrid, Legend, Line, LineChart, XAxis, YAxis,
} from "recharts";
import {
  ChartContainer, ChartTooltip, type ChartConfig,
} from "@/components/ui/chart";
import type { ModelHistoryPoint } from "@/lib/api";
import { VENTANA_DIAS, promedioMovil } from "@/lib/model-history";

const chartConfig = {
  antes: { label: "Antes de salir", color: "var(--chart-1)" },
  enVuelo: { label: "En vuelo", color: "var(--chart-2)" },
} satisfies ChartConfig;

type Fila = {
  etiqueta: string;
  antes: number | null;
  enVuelo: number | null;
};

function etiquetaDeDia(day: string): string {
  const [, mes, dia] = day.split("-");
  return `${dia}/${mes}`;
}

function Tooltip({ active, payload }: { active?: boolean; payload?: { payload: Fila }[] }) {
  if (!active || !payload?.length) return null;
  const f = payload[0].payload;
  const brecha =
    f.antes !== null && f.enVuelo !== null ? f.enVuelo - f.antes : null;

  return (
    <div className="rounded-lg border border-border bg-background px-3 py-2 text-xs shadow-md">
      <p className="font-medium">{f.etiqueta}</p>
      <dl className="mt-1 space-y-0.5 text-muted-foreground">
        <div className="flex gap-4">
          <dt>Antes de salir</dt>
          <dd className="ml-auto text-foreground tabular-nums">
            {f.antes === null ? "—" : f.antes.toFixed(3)}
          </dd>
        </div>
        <div className="flex gap-4">
          <dt>En vuelo</dt>
          <dd className="ml-auto text-foreground tabular-nums">
            {f.enVuelo === null ? "—" : f.enVuelo.toFixed(3)}
          </dd>
        </div>
        {brecha !== null && (
          <div className="flex gap-4 border-t border-border pt-1">
            <dt>Ventaja de esperar</dt>
            <dd className="ml-auto text-foreground tabular-nums">
              {brecha > 0 ? "+" : ""}
              {brecha.toFixed(3)}
            </dd>
          </div>
        )}
      </dl>
    </div>
  );
}

export function ModelPhaseChart({
  antes,
  enVuelo,
}: {
  antes: ModelHistoryPoint[];
  enVuelo: ModelHistoryPoint[];
}) {
  // Las dos series pueden no cubrir los mismos días: un día sin vuelos
  // predichos antes de salir existe en una y no en la otra.
  const dias = [...new Set([...antes, ...enVuelo].map((p) => p.day))].sort();
  const mediaAntes = promedioMovil(antes, "auc");
  const mediaEnVuelo = promedioMovil(enVuelo, "auc");

  const porDia = (
    puntos: ModelHistoryPoint[],
    media: (number | null)[],
  ): Map<string, number | null> =>
    new Map(puntos.map((p, i) => [p.day, media[i]]));

  const mapaAntes = porDia(antes, mediaAntes);
  const mapaEnVuelo = porDia(enVuelo, mediaEnVuelo);

  const filas: Fila[] = dias.map((day) => ({
    etiqueta: etiquetaDeDia(day),
    antes: mapaAntes.get(day) ?? null,
    enVuelo: mapaEnVuelo.get(day) ?? null,
  }));

  const valores = filas
    .flatMap((f) => [f.antes, f.enVuelo])
    .filter((v): v is number => v !== null);

  if (valores.length === 0) {
    return (
      <p className="flex h-[240px] items-center justify-center px-6 text-center text-xs leading-relaxed text-muted-foreground">
        Todavía no hay días suficientes con las dos fases. El corte por fase se
        empezó a guardar hace poco; la comparación aparece cuando se acumule una
        semana.
      </p>
    );
  }

  const min = Math.min(...valores);
  const max = Math.max(...valores);
  const aire = Math.max((max - min) * 0.15, 0.02);

  return (
    <ChartContainer config={chartConfig} className="h-[240px] w-full">
      <LineChart data={filas} margin={{ top: 8, right: 12, bottom: 0, left: 0 }}>
        <CartesianGrid vertical={false} strokeDasharray="3 3" />
        <XAxis
          dataKey="etiqueta"
          tickLine={false}
          axisLine={false}
          tickMargin={8}
          fontSize={11}
          minTickGap={24}
        />
        <YAxis
          tickLine={false}
          axisLine={false}
          tickMargin={8}
          fontSize={11}
          width={44}
          domain={[
            Math.max(0, Number((min - aire).toFixed(3))),
            Number((max + aire).toFixed(3)),
          ]}
          tickFormatter={(v: number) => v.toFixed(2)}
        />
        <ChartTooltip content={<Tooltip />} />
        <Legend
          verticalAlign="top"
          height={28}
          iconType="plainline"
          wrapperStyle={{ fontSize: 11 }}
        />
        <Line
          type="monotone"
          name={`Antes de salir (prom. ${VENTANA_DIAS}d)`}
          dataKey="antes"
          stroke="var(--color-antes)"
          strokeWidth={2.5}
          dot={false}
          connectNulls
          isAnimationActive={false}
        />
        <Line
          type="monotone"
          name={`En vuelo (prom. ${VENTANA_DIAS}d)`}
          dataKey="enVuelo"
          stroke="var(--color-enVuelo)"
          strokeWidth={2.5}
          strokeDasharray="5 3"
          dot={false}
          connectNulls
          isAnimationActive={false}
        />
      </LineChart>
    </ChartContainer>
  );
}

"use client";

/**
 * Evolución diaria de una métrica de calidad del modelo.
 *
 * El gráfico muestra dos cosas a la vez y no una: el valor de cada día, tenue,
 * y el promedio de siete días, marcado. El día suelto salta demasiado para leer
 * una tendencia; el promedio solo escondería que un día puntual se fue al
 * fondo.
 *
 * Los días que no llegan al mínimo de vuelos se dibujan huecos y quedan fuera
 * del promedio. Sin esa distinción, el 2026-08-18 —AUC 0.06 sobre 18 vuelos—
 * se lee como el día que el modelo colapsó, y lo que pasó es que no hubo con
 * qué medirlo.
 */

import {
  CartesianGrid, Line, LineChart, ReferenceLine, XAxis, YAxis,
} from "recharts";
import {
  ChartContainer, ChartTooltip, type ChartConfig,
} from "@/components/ui/chart";
import type { ModelHistoryPoint } from "@/lib/api";
import {
  MINIMO_CONFIABLE, VENTANA_DIAS, esConfiable, promedioMovil, type Metrica,
} from "@/lib/model-history";

const chartConfig = {
  diario: { label: "Día", color: "var(--chart-1)" },
  media: { label: `Promedio ${VENTANA_DIAS}d`, color: "var(--chart-1)" },
} satisfies ChartConfig;

type Fila = {
  day: string;
  etiqueta: string;
  diario: number | null;
  media: number | null;
  confiable: boolean;
  n_flights: number;
};

/** `2026-09-14` → `14/09`, el formato de fechas del resto de la app. */
function etiquetaDeDia(day: string): string {
  const [, mes, dia] = day.split("-");
  return `${dia}/${mes}`;
}

/**
 * Los días de muestra chica van huecos y en gris.
 *
 * Se dibujan igual en vez de omitirse: que falten días es información, y un
 * hueco en la línea no dice por qué está el hueco.
 */
function Punto(props: {
  cx?: number;
  cy?: number;
  payload?: Fila;
}) {
  const { cx, cy, payload } = props;
  if (cx === undefined || cy === undefined || !payload) return null;
  if (payload.diario === null) return null;

  return payload.confiable ? (
    <circle cx={cx} cy={cy} r={2.5} fill="var(--color-diario)" fillOpacity={0.55} />
  ) : (
    <circle
      cx={cx}
      cy={cy}
      r={3}
      fill="var(--background)"
      stroke="var(--muted-foreground)"
      strokeWidth={1.5}
    />
  );
}

function Tooltip({ active, payload }: { active?: boolean; payload?: { payload: Fila }[] }) {
  if (!active || !payload?.length) return null;
  const fila = payload[0].payload;

  return (
    <div className="rounded-lg border border-border bg-background px-3 py-2 text-xs shadow-md">
      <p className="font-medium">{fila.etiqueta}</p>
      <dl className="mt-1 space-y-0.5 text-muted-foreground">
        <div className="flex gap-3">
          <dt>Día</dt>
          <dd className="ml-auto text-foreground tabular-nums">
            {fila.diario === null ? "—" : fila.diario.toFixed(3)}
          </dd>
        </div>
        <div className="flex gap-3">
          <dt>Promedio {VENTANA_DIAS}d</dt>
          <dd className="ml-auto text-foreground tabular-nums">
            {fila.media === null ? "—" : fila.media.toFixed(3)}
          </dd>
        </div>
        <div className="flex gap-3">
          <dt>Vuelos</dt>
          <dd className="ml-auto text-foreground tabular-nums">
            {fila.n_flights}
          </dd>
        </div>
      </dl>
      {!fila.confiable && (
        <p className="mt-1.5 max-w-[15rem] border-t border-border pt-1.5 text-[11px] leading-snug text-muted-foreground">
          Menos de {MINIMO_CONFIABLE} vuelos: no entra en el promedio.
        </p>
      )}
    </div>
  );
}

export function ModelQualityChart({
  puntos,
  metrica,
  referencia,
  etiquetaReferencia,
}: {
  puntos: ModelHistoryPoint[];
  metrica: Metrica;
  /** Línea horizontal de comparación, si la métrica tiene una. */
  referencia?: number;
  etiquetaReferencia?: string;
}) {
  const media = promedioMovil(puntos, metrica);
  const filas: Fila[] = puntos.map((p, i) => ({
    day: p.day,
    etiqueta: etiquetaDeDia(p.day),
    diario: p[metrica],
    media: media[i],
    confiable: esConfiable(p),
    n_flights: p.n_flights,
  }));

  const valores = filas
    .flatMap((f) => [f.diario, f.media])
    .filter((v): v is number => v !== null);
  if (referencia !== undefined) valores.push(referencia);

  if (valores.length === 0) {
    return (
      <p className="flex h-[240px] items-center justify-center text-xs text-muted-foreground">
        Todavía no hay días con datos suficientes.
      </p>
    );
  }

  // El dominio se ajusta a lo que hay, con aire arriba y abajo: fijarlo en
  // [0,1] aplastaría toda la variación real contra una línea plana.
  const min = Math.min(...valores);
  const max = Math.max(...valores);
  const aire = Math.max((max - min) * 0.15, 0.02);

  return (
    <ChartContainer config={chartConfig} className="h-[240px] w-full">
      <LineChart data={filas} margin={{ top: 8, right: 12, bottom: 0, left: 0 }}>
        <CartesianGrid vertical={false} strokeDasharray="3 3" />
        <XAxis
          dataKey="etiqueta"
          tickLine={false}
          axisLine={false}
          tickMargin={8}
          fontSize={11}
          minTickGap={24}
        />
        <YAxis
          tickLine={false}
          axisLine={false}
          tickMargin={8}
          fontSize={11}
          width={44}
          domain={[
            Math.max(0, Number((min - aire).toFixed(3))),
            Number((max + aire).toFixed(3)),
          ]}
          tickFormatter={(v: number) => v.toFixed(2)}
        />

        {referencia !== undefined && (
          <ReferenceLine
            y={referencia}
            stroke="var(--muted-foreground)"
            strokeDasharray="4 4"
            strokeOpacity={0.6}
            label={{
              value: etiquetaReferencia,
              position: "insideTopRight",
              fontSize: 10,
              fill: "var(--muted-foreground)",
            }}
          />
        )}

        <ChartTooltip content={<Tooltip />} />

        {/* El día suelto, tenue: está para ver dispersión, no para seguirlo. */}
        <Line
          type="monotone"
          dataKey="diario"
          stroke="var(--color-diario)"
          strokeOpacity={0.3}
          strokeWidth={1}
          dot={<Punto />}
          activeDot={false}
          connectNulls
          isAnimationActive={false}
        />
        {/* El promedio, que es lo que de verdad hay que leer. */}
        <Line
          type="monotone"
          dataKey="media"
          stroke="var(--color-media)"
          strokeWidth={2.5}
          dot={false}
          activeDot={{ r: 4 }}
          connectNulls
          isAnimationActive={false}
        />
      </LineChart>
    </ChartContainer>
  );
}

/**
 * Las tres cifras que resumen si el modelo está mejorando o degradándose.
 *
 * El orden no es decorativo: primero si ordena bien (AUC), después si sus
 * números son honestos (ECE), y al final cuánto material hubo para medir. Las
 * dos primeras no significan nada sin la tercera.
 *
 * La flecha sale de `tendencia()` y no de comparar el signo acá: el ECE mejora
 * bajando, y esa inversión mal puesta pintaría de verde una calibración que
 * empeoró.
 */

import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import type { ModelHistoryPoint } from "@/lib/api";
import {
  VENTANA_DIAS, compararPeriodos, esConfiable, tendencia, type Metrica,
} from "@/lib/model-history";

const COLOR: Record<string, string> = {
  mejor: "text-risk-low",
  peor: "text-risk-high",
  igual: "text-muted-foreground",
  "sin-datos": "text-muted-foreground",
};

function Delta({ metrica, delta }: { metrica: Metrica; delta: number | null }) {
  const dir = tendencia(metrica, delta);
  if (dir === "sin-datos") {
    return (
      <span className="text-xs text-muted-foreground">
        sin semana previa para comparar
      </span>
    );
  }

  const Icono = dir === "igual" ? Minus : delta! > 0 ? ArrowUpRight : ArrowDownRight;
  const signo = delta! > 0 ? "+" : "";

  return (
    <span className={`flex items-center gap-1 text-xs ${COLOR[dir]}`}>
      <Icono className="h-3.5 w-3.5" aria-hidden="true" />
      <span className="tabular-nums">
        {signo}
        {delta!.toFixed(3)}
      </span>
      <span className="text-muted-foreground">vs. semana previa</span>
    </span>
  );
}

function Cifra({
  etiqueta,
  explicacion,
  valor,
  children,
}: {
  etiqueta: string;
  explicacion: string;
  valor: string;
  children?: React.ReactNode;
}) {
  return (
    <Card>
      <CardContent className="space-y-1">
        <p className="text-xs font-medium text-muted-foreground">{etiqueta}</p>
        <p className="text-2xl font-semibold tabular-nums">{valor}</p>
        {children}
        <p className="pt-1 text-xs leading-snug text-muted-foreground">
          {explicacion}
        </p>
      </CardContent>
    </Card>
  );
}

export function ModelQualitySummary({ puntos }: { puntos: ModelHistoryPoint[] }) {
  const auc = compararPeriodos(puntos, "auc");
  const ece = compararPeriodos(puntos, "ece");

  const confiables = puntos.filter(esConfiable);
  const vuelosPorDia =
    confiables.length > 0
      ? Math.round(
          confiables.reduce((s, p) => s + p.n_flights, 0) / confiables.length,
        )
      : null;

  return (
    <div className="grid gap-3 sm:grid-cols-3">
      <Cifra
        etiqueta="Discriminación (AUC)"
        valor={auc ? auc.actual.toFixed(3) : "—"}
        explicacion="Qué tan bien separa los vuelos que se demoran de los que no. Sube cuando mejora."
      >
        {auc && <Delta metrica="auc" delta={auc.delta} />}
      </Cifra>

      <Cifra
        etiqueta="Calibración (ECE)"
        valor={ece ? ece.actual.toFixed(3) : "—"}
        explicacion="Cuánto se aleja la probabilidad que dice de la que ocurre. Baja cuando mejora."
      >
        {ece && <Delta metrica="ece" delta={ece.delta} />}
      </Cifra>

      <Cifra
        etiqueta="Material para medir"
        valor={vuelosPorDia === null ? "—" : String(vuelosPorDia)}
        explicacion={`Vuelos aterrizados por día, promedio de los ${confiables.length} días que alcanzan el mínimo.`}
      >
        <span className="text-xs text-muted-foreground">
          media de {VENTANA_DIAS} días en las otras dos cifras
        </span>
      </Cifra>
    </div>
  );
}

