"use client";

import { useState } from "react";

import { PredictionHistoryChart } from "@/components/prediction-history-chart";
import { ShapPanel } from "@/components/shap-panel";
import { BotonColapsar } from "@/components/ui/seccion-colapsable";
import { useSeccionAbierta } from "@/lib/secciones-abiertas";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { fmtProba, fmtTime, type PredictionPoint } from "@/lib/api";

const PHASE_LABELS: Record<PredictionPoint["prediction_phase"], string> = {
  PRE_DEPARTURE: "Antes de la salida",
  EN_ROUTE: "En vuelo",
  POST_LANDING: "Vuelo finalizado",
};

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
export function PredictionEvolution({
  history,
  arrDelayMin,
}: {
  history: PredictionPoint[];
  arrDelayMin?: number | null;
}) {
  const latest = history.at(-1);
  const [selectedAt, setSelectedAt] = useState(latest?.predicted_at_utc ?? "");
  const matchedIndex = history.findIndex((cycle) => cycle.predicted_at_utc === selectedAt);
  const selectedIndex = matchedIndex >= 0 ? matchedIndex : Math.max(history.length - 1, 0);
  const selected = history[selectedIndex] ?? latest;
  const previous = selectedIndex > 0 ? history[selectedIndex - 1] : null;

  if (!selected) {
    return <PredictionHistoryChart history={history} arrDelayMin={arrDelayMin} />;
  }

  const delta = previous
    ? selected.delay_probability - previous.delay_probability
    : null;

  return (
    <div className="space-y-4">
      <PredictionHistoryChart
        history={history}
        arrDelayMin={arrDelayMin}
        selectedAt={selected.predicted_at_utc}
        onSelect={setSelectedAt}
      />

      <div className="grid gap-4 lg:grid-cols-[minmax(240px,0.75fr)_minmax(0,2fr)]">
        <CicloSeleccionado
          compacto={
            <div className="grid grid-cols-2 gap-x-4 gap-y-2 text-xs">
              <DatoCiclo etiqueta="Momento" valor={fmtTime(selected.predicted_at_utc)} />
              <DatoCiclo etiqueta="Fase" valor={PHASE_LABELS[selected.prediction_phase]} />
              <DatoCiclo etiqueta="Base" valor={fmtProba(selected.base_probability)} />
              <DatoCiclo etiqueta="Final" valor={fmtProba(selected.delay_probability)} fuerte />
              <DatoCiclo
                etiqueta="Ajuste"
                valor={`${selected.operational_adjustment >= 0 ? "+" : ""}${(
                  selected.operational_adjustment * 100
                ).toFixed(1)} pp`}
              />
              <DatoCiclo
                etiqueta="Cambio"
                valor={
                  delta === null
                    ? "Primer ciclo"
                    : `${delta >= 0 ? "+" : ""}${(delta * 100).toFixed(1)} pp`
                }
              />
              <DatoCiclo
                etiqueta="Umbral"
                valor={
                  selected.threshold_used === null
                    ? "—"
                    : fmtProba(selected.threshold_used)
                }
              />
              <DatoCiclo
                etiqueta="Estrategia"
                valor={selected.threshold_strategy?.replaceAll("_", " ") ?? "—"}
              />
            </div>
          }
          detallado={
            <>
            <CycleValue label="Momento" value={`${fmtTime(selected.predicted_at_utc)} UTC`} numero />
            <CycleValue label="Fase" value={PHASE_LABELS[selected.prediction_phase]} />
            <CycleValue label="Probabilidad base calibrada" value={fmtProba(selected.base_probability)} numero />
            <CycleValue label="Probabilidad final" value={fmtProba(selected.delay_probability)} numero emphasis />
            <CycleValue
              label="Ajuste operativo"
              value={`${selected.operational_adjustment >= 0 ? "+" : ""}${(
                selected.operational_adjustment * 100
              ).toFixed(1)} pp`}
              numero
            />
            <CycleValue
              label="Cambio vs. ciclo anterior"
              value={
                delta === null
                  ? "Primer ciclo"
                  : `${delta >= 0 ? "+" : ""}${(delta * 100).toFixed(1)} pp`
              }
              numero={delta !== null}
            />
            <CycleValue
              label="Umbral usado"
              value={selected.threshold_used === null ? "No registrado" : fmtProba(selected.threshold_used)}
              numero={selected.threshold_used !== null}
            />
            <CycleValue
              label="Estrategia de umbral"
              value={selected.threshold_strategy?.replaceAll("_", " ") ?? "No registrada"}
            />
            </>
          }
        />

        <ShapPanel factors={selected.shap} />
      </div>
    </div>
  );
}

function CycleValue({
  label,
  value,
  numero = false,
  emphasis = false,
}: {
  label: string;
  value: string;
  /**
   * Los valores de esta tarjeta son todos cifras —horarios, probabilidades,
   * puntos porcentuales—, nunca identificadores. Antes iban en la familia
   * monoespaciada, que es la de los códigos; lo que hace falta acá es que los
   * dígitos se alineen en columna, y eso lo da `tabular-nums` sin cambiar de
   * familia tipográfica.
   */
  numero?: boolean;
  emphasis?: boolean;
}) {
  return (
    <div className="flex items-start justify-between gap-3 border-b border-border/70 pb-2 last:border-0 last:pb-0">
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className={`${numero ? "tabular-nums" : ""} ${emphasis ? "font-semibold" : ""} text-right text-xs`}>
        {value}
      </span>
    </div>
  );
}


/**
 * El detalle del ciclo elegido, cerrado por omisión.
 *
 * Son siete filas —momento, fase, probabilidad base, final, ajuste operativo,
 * cambio contra el ciclo anterior, umbral y estrategia— y casi siempre lo que
 * se mira es la probabilidad, que queda en el resumen. Abierto está todo.
 */
function CicloSeleccionado({
  compacto,
  detallado,
}: {
  compacto: React.ReactNode;
  detallado: React.ReactNode;
}) {
  const { abierto, alternar } = useSeccionAbierta("ciclo-seleccionado", false);
  return (
    <Card>
      <CardHeader className="pb-3">
        <BotonColapsar
          abierto={abierto}
          onToggle={alternar}
          titulo={
            <CardTitle className="text-sm font-medium">
              Ciclo seleccionado
            </CardTitle>
          }
        />
      </CardHeader>
      <CardContent className={abierto ? "space-y-3 text-sm" : "pb-4"}>
        {abierto ? detallado : compacto}
      </CardContent>
    </Card>
  );
}

/** Un valor del ciclo en su forma apretada. */
function DatoCiclo({
  etiqueta,
  valor,
  fuerte = false,
}: {
  etiqueta: string;
  valor: React.ReactNode;
  fuerte?: boolean;
}) {
  return (
    <div className="min-w-0">
      <p className="text-[11px] text-muted-foreground">{etiqueta}</p>
      <div className={fuerte ? "font-semibold tabular-nums" : "tabular-nums"}>
        {valor}
      </div>
    </div>
  );
}

"use client";

import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip,
  ReferenceLine, ResponsiveContainer,
} from "recharts";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { fmtTime, type PredictionPoint } from "@/lib/api";

function asUTC(utc: string): Date {
  return new Date(/[Z+]/.test(utc) ? utc : utc + "Z");
}

// Se arma a mano y no con `toLocaleTimeString`: `es-AR` sin `hour12` resuelve
// a reloj de 12 horas. Ver el comentario de `fmtTime` en lib/api.ts.
function fmtAxisTime(utc: string) {
  const d = asUTC(utc);
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mi = String(d.getUTCMinutes()).padStart(2, "0");
  return `${hh}:${mi}`;
}

// Reusa `fmtTime` en vez de repetir el formato: la versión propia armaba la
// fecha con el locale y devolvía `1/10`, porque `es-AR` ignora
// `day: "2-digit"`. Un solo lugar donde equivocarse.
function fmtTooltipTime(utc: string) {
  return `${fmtTime(utc)} UTC`;
}

function riskColor(proba: number) {
  if (proba >= 35) return "var(--color-risk-high)";
  if (proba >= 15) return "var(--color-risk-medium)";
  return "var(--color-risk-low)";
}

export function PredictionHistoryChart({
  history,
  arrDelayMin,
  selectedAt,
  onSelect,
}: {
  history: PredictionPoint[];
  arrDelayMin?: number | null;
  selectedAt?: string;
  onSelect?: (predictedAt: string) => void;
}) {
  const hasActual = arrDelayMin !== null && arrDelayMin !== undefined;
  const actuallyDelayed = hasActual && arrDelayMin! > 15;

  if (history.length === 0) {
    return (
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-medium">Evolución de predicciones</CardTitle>
          <CardDescription>Historial de ciclos de 30 min</CardDescription>
        </CardHeader>
        <CardContent>
          <p className="py-8 text-center text-sm text-muted-foreground">
            Sin historial de predicciones aún.
          </p>
        </CardContent>
      </Card>
    );
  }

  const data = history.map((p) => ({
    predictedAt: p.predicted_at_utc,
    time: fmtAxisTime(p.predicted_at_utc),
    fullTime: fmtTooltipTime(p.predicted_at_utc),
    proba: Math.round(p.delay_probability * 100),
  }));

  const latestProba = data[data.length - 1].proba;
  const color = riskColor(latestProba);

  const header = (
    <CardHeader className="pb-2">
      <CardTitle className="text-sm font-medium flex items-center gap-2">
        Evolución de predicciones
        {hasActual && (
          <span className={`text-[11px] font-medium px-2 py-0.5 rounded-full ${
            actuallyDelayed
              ? "bg-risk-high/10 text-risk-high"
              : "bg-risk-low/10 text-risk-low"
          }`}>
            {actuallyDelayed
              ? `Resultado: demorado (+${Math.round(arrDelayMin!)} min)`
              : "Resultado: a tiempo"}
          </span>
        )}
      </CardTitle>
      <CardDescription>
        {history.length} {history.length === 1 ? "ciclo registrado" : "ciclos registrados"} · actualización cada 15 min
      </CardDescription>
    </CardHeader>
  );

  if (data.length === 1) {
    return (
      <Card>
        {header}
        <CardContent>
          <div className="flex flex-col items-center justify-center gap-2 py-6">
            <div className="text-4xl font-bold tabular-nums" style={{ color }}>
              {latestProba}%
            </div>
            <div className="text-xs text-muted-foreground">{data[0].fullTime}</div>
            <div className="text-[11px] text-muted-foreground">Primer ciclo — se mostrará evolución en el siguiente</div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      {header}
      <CardContent>
        <ResponsiveContainer width="100%" height={190}>
          <AreaChart data={data} margin={{ top: 8, right: 52, bottom: 0, left: 0 }}>
            <defs>
              <linearGradient id="probaGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.25} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
            <XAxis
              dataKey="time"
              tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
              tickLine={false}
              axisLine={false}
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
              tickFormatter={(v) => `${v}%`}
              tickLine={false}
              axisLine={false}
              width={38}
            />
            <Tooltip
              content={({ active, payload }) => {
                if (!active || !payload?.length) return null;
                const d = payload[0].payload as { fullTime: string; proba: number };
                return (
                  <div className="rounded border bg-popover px-3 py-2 text-xs shadow-md">
                    <p className="text-muted-foreground">{d.fullTime}</p>
                    <p className="mt-0.5 font-semibold">{d.proba}% prob. retraso</p>
                  </div>
                );
              }}
            />
            <ReferenceLine
              y={35}
              stroke="var(--color-risk-high)"
              strokeDasharray="4 2"
              strokeWidth={1.5}
              strokeOpacity={0.9}
              label={{ value: "Alto 35%", position: "insideTopRight", fontSize: 10, fill: "var(--color-risk-high)", dy: -6 }}
            />
            <ReferenceLine
              y={15}
              stroke="var(--color-risk-medium)"
              strokeDasharray="4 2"
              strokeWidth={1.5}
              strokeOpacity={0.9}
              label={{ value: "Medio 15%", position: "insideTopRight", fontSize: 10, fill: "var(--color-risk-medium)", dy: -6 }}
            />
            <Area
              type="linear"
              dataKey="proba"
              stroke={color}
              strokeWidth={2}
              fill="url(#probaGrad)"
              dot={(props: HistoryDotProps) => (
                <HistoryDot
                  {...props}
                  selected={props.payload?.predictedAt === selectedAt}
                  onSelect={onSelect}
                />
              )}
              activeDot={{ r: 5, fill: color }}
            />
          </AreaChart>
        </ResponsiveContainer>
        <div
          className="mt-3 flex gap-2 overflow-x-auto pb-1"
          aria-label="Ciclos de predicción disponibles"
        >
          {data.map((cycle, index) => (
            <button
              key={cycle.predictedAt}
              type="button"
              aria-pressed={cycle.predictedAt === selectedAt}
              onClick={() => onSelect?.(cycle.predictedAt)}
              className={`min-w-24 rounded-md border px-2.5 py-2 text-left text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                cycle.predictedAt === selectedAt
                  ? "border-primary bg-primary/10"
                  : "border-border bg-background hover:bg-muted"
              }`}
            >
              <span className="block text-[10px] text-muted-foreground">
                Ciclo {index + 1}
              </span>
              <span className="block font-semibold tabular-nums" style={{ color: riskColor(cycle.proba) }}>
                {cycle.proba}%
              </span>
              <span className="block text-[10px] text-muted-foreground">{cycle.time} UTC</span>
            </button>
          ))}
        </div>
        <p className="mt-1 text-[11px] text-muted-foreground">
          Actualización cada 15 min · Umbrales:{" "}
          <span className="text-risk-medium">15% medio</span>{" · "}
          <span className="text-risk-high">35% alto</span>
        </p>
      </CardContent>
    </Card>
  );
}

type ChartDatum = {
  predictedAt: string;
  proba: number;
};

type HistoryDotProps = {
  cx?: number;
  cy?: number;
  payload?: ChartDatum;
  selected?: boolean;
  onSelect?: (predictedAt: string) => void;
};

function HistoryDot({ cx, cy, payload, selected, onSelect }: HistoryDotProps) {
  if (cx === undefined || cy === undefined || !payload) return <g />;
  return (
    <circle
      cx={cx}
      cy={cy}
      r={selected ? 5 : 3.5}
      fill={riskColor(payload.proba)}
      stroke="hsl(var(--background))"
      strokeWidth={selected ? 2.5 : 1.5}
      className="cursor-pointer"
      onClick={() => onSelect?.(payload.predictedAt)}
    />
  );
}

