/**
 * Cambiar el perfil en Ajustes tiene que verse.
 *
 * Había dos controles: el perfil de la cuenta (Viajero / Operaciones, guardado
 * en el servidor) y un "cambio de vista" local que la propia pantalla describe
 * como *temporal, solo en este navegador, para demos*.
 *
 * No era temporal. El valor local le gana al de la cuenta:
 *
 *     profile = canSelectProfile
 *       ? storedProfile ?? accountProfile ?? DEFAULT_PROFILE
 *       : accountProfile ?? "passenger";
 *
 * y el desplegable solo ofrecía los dos perfiles, nunca "seguir mi cuenta".
 * Un admin que lo abriera una vez quedaba con la vista congelada en ese
 * navegador, y cambiar el perfil en Ajustes no hacía nada visible.
 *
 * Se verifica sobre la fuente porque lo que falla es la precedencia entre dos
 * piezas que viven en archivos distintos, y ningún render de un componente
 * solo lo expone.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const raiz = process.cwd();
const PROVIDER = readFileSync(
  join(raiz, "src", "components", "providers", "profile-provider.tsx"),
  "utf8",
);
const SWITCHER = readFileSync(
  join(raiz, "src", "components", "profile-switcher.tsx"),
  "utf8",
);
const AJUSTES = readFileSync(
  join(raiz, "src", "app", "settings", "page.tsx"),
  "utf8",
);

describe("el override local se puede soltar", () => {
  it("setProfile acepta null para volver a seguir la cuenta", () => {
    expect(PROVIDER).toMatch(/setProfile:\s*\(profile:\s*ProfileId\s*\|\s*null\)/);
  });

  it("y null BORRA la cookie en vez de guardar un valor", () => {
    // El override pasó de `localStorage` a una cookie para que el servidor
    // también lo vea: la home es un Server Component y decide qué árbol
    // dibujar según el perfil. Borrar es poner una fecha pasada.
    expect(PROVIDER).toContain("expires=Thu, 01 Jan 1970");
    expect(PROVIDER).toContain("writeCookie(next)");
  });

  it("el servidor lee el mismo override que el cliente", () => {
    // Si las dos piezas leyeran lugares distintos, la misma pantalla
    // terminaría con el menú de un perfil y el contenido del otro.
    const servidor = readFileSync(
      join(raiz, "src", "lib", "server-profile.ts"),
      "utf8",
    );
    expect(servidor).toContain('"ontimeai-profile"');
    expect(PROVIDER).toContain('STORAGE_KEY = "ontimeai-profile"');
  });

  it("expone si hay un override activo, para poder decirlo en pantalla", () => {
    expect(PROVIDER).toMatch(/overridden:/);
  });
});

describe("el desplegable ofrece el camino de vuelta", () => {
  it("tiene una opción para seguir la cuenta", () => {
    expect(SWITCHER).toContain("Seguir mi cuenta");
  });

  it("que limpia el override", () => {
    expect(SWITCHER).toContain("setProfile(null)");
  });
});

describe("cambiar el perfil de la cuenta se ve", () => {
  it("limpia el override antes de recargar", () => {
    // El orden importa: si el override sobrevive a la recarga, le gana al
    // perfil recién elegido y el cambio queda invisible.
    const i = AJUSTES.indexOf("setProfile(null)");
    const j = AJUSTES.indexOf("window.location.reload()");
    expect(i).toBeGreaterThan(-1);
    expect(j).toBeGreaterThan(i);
  });

  it("avisa en pantalla cuando hay una vista fijada", () => {
    expect(AJUSTES).toContain("overridden");
    expect(AJUSTES).toMatch(/vista fijada/i);
  });
});

"use client";

import * as React from "react";
import { usePathname } from "next/navigation";

import { apiMe } from "@/lib/api";
import { appPath } from "@/lib/mobile-env";
import type { SessionUser } from "@/lib/auth-types";
import { SessionProvider } from "@/components/providers/session-provider";

/**
 * Resuelve la sesión del lado del cliente y guarda las rutas privadas.
 *
 * Es el reemplazo de `src/proxy.ts` en el bundle empaquetado. En la web ese
 * archivo corre en el servidor antes de cada request: si no hay cookie, redirige
 * a /login sin que el navegador llegue a ver la página. Un export estático no
 * tiene dónde correr eso — los HTML ya están escritos y el teléfono los abre
 * desde el disco—, así que el corte se hace acá, al montar.
 *
 * La diferencia de garantías hay que decirla: esto NO es un control de acceso.
 * Cualquiera con el .ipa puede leer el HTML de /admin sin autenticarse. Lo que
 * lo hace irrelevante es que esos HTML no traen datos adentro: todo lo que se
 * muestra sale de llamadas al backend que el propio backend autoriza por rol.
 * Sin token no hay datos, y con un token de rol `user` el backend devuelve 403.
 * Este gate es UX —no mostrar un dashboard vacío—, y la autorización real vive
 * donde siempre vivió.
 *
 * El árbol se monta recién cuando la sesión está resuelta. Renderizar los hijos
 * antes haría que cada página dispare sus fetch con el token todavía sin leer
 * del almacenamiento nativo, y todas cobrarían un 401 en el arranque.
 */
export function NativeSessionGate({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  // Las mismas rutas que proxy.ts deja ver sin sesión: entrar y registrarse.
  const isAuthRoute =
    (pathname?.startsWith("/login") || pathname?.startsWith("/signup")) ?? false;

  const [user, setUser] = React.useState<SessionUser | null>(null);
  const [status, setStatus] = React.useState<"resolving" | "ready" | "failed">(
    "resolving",
  );
  const [failure, setFailure] = React.useState("");

  React.useEffect(() => {
    let alive = true;

    // eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
    (async () => {
      try {
        const { loadToken, clearToken } = await import(
          "@/lib/native/session"
        );
        const token = await loadToken();

        let session: SessionUser | null = null;
        if (token) {
          try {
            session = await apiMe();
          } catch {
            // El token no sirve (expiró, o el backend lo rechaza). `get()` ya
            // lo borró si la respuesta fue 401; para cualquier otra falla lo
            // limpiamos acá, porque una sesión que no se puede validar no es
            // una sesión.
            await clearToken();
            session = null;
          }
        }

        if (!alive) return;

        // Las mismas dos reglas que aplica proxy.ts en la web.
        if (!session && !isAuthRoute) {
          window.location.replace(appPath("/login"));
          return;
        }
        if (session && isAuthRoute) {
          window.location.replace(appPath("/"));
          return;
        }

        setUser(session);
        setStatus("ready");
      } catch (error) {
        // Sin este catch cualquier falla acá —un chunk que no carga, el puente
        // nativo que no responde— dejaba la promesa rechazada sin que nadie la
        // observe, `status` en "resolving" para siempre, y la app en una
        // pantalla vacía indistinguible de un cuelgue. Un arranque que falla
        // tiene que poder decirlo.
        if (!alive) return;
        setFailure(error instanceof Error ? error.message : String(error));
        setStatus("failed");
      }
    })();

    return () => {
      alive = false;
    };
    // Corre una sola vez por arranque: las navegaciones internas son del router
    // de Next y no vuelven a montar el layout raíz. Revalidar en cada cambio de
    // ruta pagaría un /auth/me por navegación sin agregar garantía — el backend
    // valida el token en cada llamada de todos modos.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  React.useEffect(() => {
    // React montó: el bundle carga y ejecuta, que es lo único que el plugin tiene
    // que saber para no revertirlo. Va antes de resolver la sesión a propósito
    // —ver `lib/native/app-ready.ts`—: un /auth/me lento no es un bundle roto.
    void import("@/lib/native/app-ready").then((m) => m.notifyAppReady());
  }, []);

  React.useEffect(() => {
    if (status === "resolving") return;
    // Hay una pantalla real arriba —o una que explica por qué no la hay—:
    // bajar el splash. También en el caso de error, porque un splash que no
    // baja nunca es peor que un mensaje.
    void import("@/lib/native/app-ready").then((m) => m.hideSplash());
  }, [status]);

  if (status === "failed") {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center gap-4 bg-background px-6 text-center">
        <h1 className="text-lg font-semibold text-foreground">
          No se pudo iniciar la app
        </h1>
        <p className="max-w-sm text-sm text-muted-foreground">
          {failure || "Error desconocido al resolver la sesión."}
        </p>
        <button
          type="button"
          onClick={() => window.location.reload()}
          className="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground"
        >
          Reintentar
        </button>
      </div>
    );
  }

  // Mientras resuelve, el splash nativo sigue tapando la pantalla. Este fondo
  // es lo que evita el flash blanco en el instante entre que el splash baja y
  // React pinta.
  if (status === "resolving") {
    return <div className="min-h-screen bg-background" aria-hidden />;
  }

  return <SessionProvider user={user}>{children}</SessionProvider>;
}

"use client";

import * as React from "react";
import { useSession } from "@/components/providers/session-provider";
import { profileIdForUserType } from "@/lib/auth-types";

export type ProfileId = "airline" | "passenger";

export const PROFILES: Array<{
  id: ProfileId;
  label: string;
  description: string;
}> = [
  {
    id: "airline",
    label: "Aerolínea / Operador",
    description: "Gestión operativa de la flota en ATL",
  },
  {
    id: "passenger",
    label: "Pasajero",
    description: "Consulta de riesgo de retraso de mi vuelo",
  },
];

/**
 * El override va en una COOKIE y no en `localStorage`.
 *
 * La home es un Server Component y decide qué árbol dibujar según el perfil.
 * El servidor no ve `localStorage`, así que con el almacenamiento anterior la
 * barra de navegación respetaba el override y el contenido no: dos piezas de
 * la misma pantalla discrepando sobre quién sos.
 *
 * No lleva `HttpOnly` a propósito: lo escribe el navegador. Tampoco es un
 * secreto —dice qué vista mirás— y el servidor nunca lo usa para autorizar
 * nada, solo para elegir maqueta.
 */
const STORAGE_KEY = "ontimeai-profile";
const DEFAULT_PROFILE: ProfileId = "airline";
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** Local override, only meaningful for roles allowed to switch views. */
function getStoredProfile(): ProfileId | null {
  const match = document.cookie.match(
    new RegExp(`(?:^|;\\s*)${STORAGE_KEY}=(airline|passenger)(?:;|$)`),
  );
  return (match?.[1] as ProfileId | undefined) ?? null;
}

function writeCookie(value: ProfileId | null) {
  // Un año para el override y fecha pasada para borrarlo: así se comporta
  // igual en todos los navegadores sin depender de `max-age=0`.
  const caduca = value
    ? `max-age=${60 * 60 * 24 * 365}`
    : "expires=Thu, 01 Jan 1970 00:00:00 GMT";
  document.cookie = `${STORAGE_KEY}=${value ?? ""}; path=/; ${caduca}; samesite=lax`;
}

type ProfileContextValue = {
  profile: ProfileId;
  /** `null` vuelve a seguir el perfil de la cuenta. */
  setProfile: (profile: ProfileId | null) => void;
  /** Si hay un override local pisando al perfil de la cuenta. */
  overridden: boolean;
  /** El perfil que dicta la cuenta, sin el override. */
  accountProfile: ProfileId | null;
};

const ProfileContext = React.createContext<ProfileContextValue | undefined>(
  undefined,
);

export function ProfileProvider({ children }: { children: React.ReactNode }) {
  const { user } = useSession();
  const storedProfile = React.useSyncExternalStore(
    subscribe,
    getStoredProfile,
    () => null,
  );

  // The account's own segment (set during onboarding) is the source of truth.
  const accountProfile = user?.userType
    ? profileIdForUserType(user.userType)
    : null;
  // Operators and admins can still flip the view locally, e.g. to run a demo.
  const canSelectProfile =
    user?.role === "admin" || user?.role === "superadmin";

  const profile = canSelectProfile
    ? storedProfile ?? accountProfile ?? DEFAULT_PROFILE
    : accountProfile ?? "passenger";

  const setProfile = React.useCallback((next: ProfileId | null) => {
    if (!canSelectProfile) return;
    // `null` BORRA el override en vez de guardar un valor.
    //
    // Antes no habia forma de volver atras: el desplegable solo ofrecia
    // "airline" o "passenger", nunca "seguir mi cuenta", y lo guardado le gana
    // al perfil de la cuenta. Un admin que abriera el desplegable una vez
    // quedaba con la vista congelada en ese navegador para siempre, y cambiar
    // el perfil en Ajustes no hacia nada visible.
    writeCookie(next);
    listeners.forEach((listener) => listener());
    // La home la dibuja el servidor según esta cookie, así que hay que pedirle
    // el árbol nuevo. Sin esto cambia el menú y el contenido se queda igual.
    window.location.reload();
  }, [canSelectProfile]);

  const value = React.useMemo(
    () => ({
      profile,
      setProfile,
      overridden: canSelectProfile && storedProfile !== null,
      accountProfile,
    }),
    [profile, setProfile, canSelectProfile, storedProfile, accountProfile],
  );

  return (
    <ProfileContext.Provider value={value}>{children}</ProfileContext.Provider>
  );
}

export function useProfile() {
  const ctx = React.useContext(ProfileContext);
  if (!ctx) throw new Error("useProfile must be used within ProfileProvider");
  return ctx;
}

"use client";

import * as React from "react";

import type { SessionUser } from "@/lib/auth-types";

type SessionContextValue = {
  user: SessionUser | null;
};

const SessionContext = React.createContext<SessionContextValue | undefined>(
  undefined,
);

export function SessionProvider({
  user,
  children,
}: {
  user: SessionUser | null;
  children: React.ReactNode;
}) {
  React.useEffect(() => {
    // Remove tokens left by versions prior to the HttpOnly-cookie migration.
    window.localStorage.removeItem("ontimeai-auth-token");
  }, []);

  const value = React.useMemo(() => ({ user }), [user]);
  return (
    <SessionContext.Provider value={value}>{children}</SessionContext.Provider>
  );
}

export function useSession() {
  const value = React.useContext(SessionContext);
  if (!value) throw new Error("useSession must be used within SessionProvider");
  return value;
}

"use client";

import * as React from "react";
import { ChevronDown, Copy, ExternalLink } from "lucide-react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export function RawPayloadPanel({
  title,
  description,
  url,
  payload,
  defaultOpen = false,
}: {
  title: string;
  description?: string;
  url?: string;
  payload: unknown;
  defaultOpen?: boolean;
}) {
  const [open, setOpen] = React.useState(defaultOpen);
  const [copied, setCopied] = React.useState(false);

  const json = React.useMemo(() => JSON.stringify(payload, null, 2), [payload]);
  const bytes = new Blob([json]).size;

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(json);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* ignore */
    }
  };

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-3">
          <div className="flex-1 space-y-1">
            <CardTitle className="text-sm font-medium">{title}</CardTitle>
            {description ? (
              <CardDescription className="text-xs">
                {description}
              </CardDescription>
            ) : null}
            {url ? (
              <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-1 inline-flex items-center gap-1 font-mono text-[11px] text-primary hover:underline"
              >
                <ExternalLink className="size-3" />
                {url}
              </a>
            ) : null}
          </div>
          <div className="flex shrink-0 items-center gap-2">
            <span className="font-mono text-[11px] text-muted-foreground">
              {(bytes / 1024).toFixed(1)} KB
            </span>
            <Button
              variant="outline"
              size="icon-sm"
              onClick={copy}
              aria-label="Copiar JSON"
            >
              <Copy className="size-3.5" />
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setOpen((v) => !v)}
              className="gap-1"
            >
              <ChevronDown
                className={cn(
                  "size-3.5 transition-transform",
                  open && "rotate-180",
                )}
              />
              {open ? "Ocultar" : "Ver JSON"}
            </Button>
          </div>
        </div>
        {copied ? (
          <span className="absolute right-4 top-14 rounded bg-primary px-2 py-0.5 text-[10px] font-medium text-primary-foreground">
            Copiado
          </span>
        ) : null}
      </CardHeader>
      {open ? (
        <CardContent>
          <pre className="max-h-[480px] overflow-auto rounded-md border bg-muted/40 p-3 font-mono text-[11px] leading-relaxed text-muted-foreground">
            {json}
          </pre>
        </CardContent>
      ) : null}
    </Card>
  );
}

