import { api, type Flight } from "@/lib/api";
import { HomeViajeroView } from "@/components/viajero/home-viajero-view";
import { proximasSalidas } from "@/components/viajero/proximos-vuelos";

/**
 * Trae los vuelos y resuelve cuáles son los próximos.
 *
 * El reloj se lee acá y no en el componente: `Date.now()` dentro del render
 * hace que el mismo árbol devuelva cosas distintas sin que cambien sus props,
 * y React lo rechaza con razón. Esta función no es un componente.
 */
async function cargar(): Promise<{ vuelos: Flight[]; proximos: Flight[] }> {
  let vuelos: Flight[] = [];
  try {
    vuelos = await api.flights();
  } catch {
    vuelos = [];
  }
  return { vuelos, proximos: proximasSalidas(vuelos, Date.now()) };
}

/**
 * La home del perfil viajero en la web: trae los vuelos en el servidor durante
 * el render y delega el dibujo en `HomeViajeroView`.
 *
 * El bundle de iOS reemplaza este archivo por
 * `mobile/components/home-viajero.tsx`, que pide lo mismo al montar: en un
 * export estático este render corre una sola vez, en build time, y congelaría
 * la lista de vuelos de ese momento.
 */
export async function HomeViajero() {
  const { vuelos, proximos } = await cargar();
  return <HomeViajeroView vuelos={vuelos} proximos={proximos} />;
}

"use client";

import * as React from "react";
import Link from "next/link";
import { Archive, Bookmark, Plane, RotateCw, Trash2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { RiskBadge } from "@/components/risk-badge";
import { api, fmtTime, type SavedFlight } from "@/lib/api";
import { flightDetailHref } from "@/lib/routes";

/**
 * Los vuelos guardados, del más próximo al más viejo.
 *
 * La lista mezcla dos clases de fila y eso es a propósito. Un vuelo guardado
 * hace tres semanas ya no existe en `live_data.db` —el pipeline purga a los
 * 14 días— así que vuelve del backend marcado como `archived`, con la copia
 * de su número y su ruta pero sin predicción. Se muestra igual, apagado: el
 * pedido es que los guardados queden históricamente, y una lista que borra
 * sola lo viejo no cumple eso.
 */
export function MisVuelosView({
  iniciales,
  fallo = false,
}: {
  iniciales: SavedFlight[];
  /** La lista no se pudo traer. Distinto de no tener ninguno guardado. */
  fallo?: boolean;
}) {
  const [vuelos, setVuelos] = React.useState(iniciales);
  const [quitando, setQuitando] = React.useState<string | null>(null);

  async function quitar(id: string) {
    setQuitando(id);
    const previos = vuelos;
    setVuelos((v) => v.filter((x) => x.fa_flight_id !== id));
    try {
      await api.unsaveFlight(id);
    } catch {
      setVuelos(previos); // si falla, la fila vuelve
    } finally {
      setQuitando(null);
    }
  }

  // Primero el fallo: decirle "no guardaste nada" a alguien que si guardo, y
  // encima invitarlo a buscar otro vuelo, es peor que no mostrar nada.
  if (fallo && vuelos.length === 0) {
    return (
      <Card>
        <CardContent className="flex flex-col items-center gap-3 py-14 text-center">
          <RotateCw className="size-8 text-muted-foreground/60" />
          <p className="text-sm font-medium">No pudimos traer tus vuelos</p>
          <p className="max-w-sm text-sm text-muted-foreground">
            Puede ser una caída momentánea. Tus vuelos guardados siguen ahí.
          </p>
          <Button
            variant="outline"
            className="mt-1"
            onClick={() => window.location.reload()}
          >
            Reintentar
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (vuelos.length === 0) {
    return (
      <Card>
        <CardContent className="flex flex-col items-center gap-3 py-14 text-center">
          <Bookmark className="size-8 text-muted-foreground/60" />
          <p className="text-sm font-medium">Todavía no guardaste ningún vuelo</p>
          <p className="max-w-sm text-sm text-muted-foreground">
            Buscá tu vuelo desde el inicio y tocá «Guardar». Van a quedar acá,
            incluso después de que hayan volado.
          </p>
          <Button
            variant="outline"
            className="mt-1"
            render={<Link href="/" />}
          >
            Buscar un vuelo
          </Button>
        </CardContent>
      </Card>
    );
  }

  const activos = vuelos.filter((v) => !v.archived);
  const archivados = vuelos.filter((v) => v.archived);

  return (
    <div className="space-y-6">
      {activos.length > 0 ? (
        <Seccion titulo="En seguimiento">
          {activos.map((v) => (
            <Fila
              key={v.fa_flight_id}
              vuelo={v}
              quitando={quitando === v.fa_flight_id}
              onQuitar={quitar}
            />
          ))}
        </Seccion>
      ) : null}

      {archivados.length > 0 ? (
        <Seccion
          titulo="Ya volaron"
          nota="Guardamos el vuelo, pero su predicción ya salió del sistema."
        >
          {archivados.map((v) => (
            <Fila
              key={v.fa_flight_id}
              vuelo={v}
              quitando={quitando === v.fa_flight_id}
              onQuitar={quitar}
            />
          ))}
        </Seccion>
      ) : null}
    </div>
  );
}

function Seccion({
  titulo,
  nota,
  children,
}: {
  titulo: string;
  nota?: string;
  children: React.ReactNode;
}) {
  return (
    <section className="space-y-2">
      <div>
        <h2 className="text-sm font-medium text-muted-foreground">{titulo}</h2>
        {nota ? <p className="text-xs text-muted-foreground/80">{nota}</p> : null}
      </div>
      <Card>
        <CardContent className="px-0 py-0">
          <ul className="divide-y">{children}</ul>
        </CardContent>
      </Card>
    </section>
  );
}

function Fila({
  vuelo,
  quitando,
  onQuitar,
}: {
  vuelo: SavedFlight;
  quitando: boolean;
  onQuitar: (id: string) => void;
}) {
  const numero = vuelo.flight_number ?? vuelo.ident_iata ?? vuelo.fa_flight_id;
  const destino = vuelo.destination ?? vuelo.dest ?? "—";
  const Icono = vuelo.archived ? Archive : Plane;

  return (
    <li className="flex items-center gap-3 px-6 py-3">
      <Icono className="size-4 shrink-0 text-muted-foreground" />
      <Link
        href={flightDetailHref(vuelo.fa_flight_id)}
        className="min-w-0 flex-1"
      >
        <div className="flex items-baseline gap-2">
          <span className="font-mono text-sm font-semibold">{numero}</span>
          <span className="truncate text-sm text-muted-foreground">
            hacia {destino}
          </span>
        </div>
        <div className="text-xs tabular-nums text-muted-foreground">
          {vuelo.scheduled_out_utc ? `${fmtTime(vuelo.scheduled_out_utc)} UTC` : "—"}
        </div>
      </Link>

      {vuelo.risk ? (
        <RiskBadge risk={vuelo.risk} />
      ) : (
        <span className="text-xs text-muted-foreground">sin predicción</span>
      )}

      <Button
        variant="ghost"
        size="icon-sm"
        onClick={() => onQuitar(vuelo.fa_flight_id)}
        disabled={quitando}
        aria-label={`Quitar ${numero} de mis vuelos`}
        className="text-muted-foreground hover:text-destructive"
      >
        <Trash2 className="size-4" />
      </Button>
    </li>
  );
}

import Link from "next/link";
import { Plane } from "lucide-react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { RiskBadge } from "@/components/risk-badge";
import { fmtTime, toUTCDate, type Flight } from "@/lib/api";
import { flightDetailHref } from "@/lib/routes";

/**
 * Las que todavía no salieron, ordenadas y recortadas a doce.
 *
 * Doce y no las 769 del día: esto no es la tabla de operaciones, es lo que
 * está por salir. Quien busca un vuelo puntual usa el buscador de arriba.
 *
 * Va fuera del componente a propósito: lee el reloj, y un componente que
 * cambia de resultado sin que cambien sus props no es puro. React lo marca,
 * y con razón.
 */
export function proximasSalidas(vuelos: Flight[], ahora: number): Flight[] {
  return vuelos
    .filter((v) => {
      if (v.actual_out_utc || v.actual_off_utc) return false;
      const salida = v.estimated_out_utc || v.scheduled_out_utc;
      return Boolean(salida) && toUTCDate(salida).getTime() > ahora;
    })
    .sort(
      (a, b) =>
        toUTCDate(a.estimated_out_utc || a.scheduled_out_utc).getTime() -
        toUTCDate(b.estimated_out_utc || b.scheduled_out_utc).getTime(),
    )
    .slice(0, 12);
}

/** La lista ya viene filtrada por `proximasSalidas`. */
export function ProximosVuelos({ vuelos: proximos }: { vuelos: Flight[] }) {
  if (proximos.length === 0) {
    return (
      <Card>
        <CardContent className="py-10 text-center text-sm text-muted-foreground">
          No hay salidas próximas en este momento.
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium text-muted-foreground">
          Próximas salidas de Atlanta
        </CardTitle>
      </CardHeader>
      <CardContent className="px-0 pb-0">
        <ul className="divide-y">
          {proximos.map((v) => {
            const salida = v.estimated_out_utc || v.scheduled_out_utc;
            const demorado =
              v.estimated_out_utc &&
              v.scheduled_out_utc &&
              toUTCDate(v.estimated_out_utc).getTime() >
                toUTCDate(v.scheduled_out_utc).getTime() + 60_000;
            return (
              <li key={v.fa_flight_id}>
                <Link
                  href={flightDetailHref(v.fa_flight_id)}
                  className="flex items-center gap-3 px-6 py-3 transition-colors hover:bg-accent/50"
                >
                  <Plane className="size-4 shrink-0 text-muted-foreground" />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-baseline gap-2">
                      <span className="font-mono text-sm font-semibold">
                        {v.flight_number}
                      </span>
                      <span className="truncate text-sm text-muted-foreground">
                        hacia {v.destination}
                      </span>
                    </div>
                    <div className="text-xs tabular-nums text-muted-foreground">
                      {fmtTime(salida)} UTC
                      {demorado ? (
                        <span className="ml-1 text-risk-medium">
                          · estimada, salía {fmtTime(v.scheduled_out_utc)}
                        </span>
                      ) : null}
                    </div>
                  </div>
                  <RiskBadge risk={v.risk} />
                </Link>
              </li>
            );
          })}
        </ul>
      </CardContent>
    </Card>
  );
}

/**
 * Render del panel meteorológico, sin fetch. Ver `metric-cards-view.tsx`
 * para el porqué de la separación.
 */
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { AlertTriangle, Cloud, Eye, Thermometer, Wind } from "lucide-react";
import { type WeatherData } from "@/lib/api";
import { cn } from "@/lib/utils";

function toF(c: number | null): string {
  if (c === null) return "—";
  return `${Math.round(c * 9 / 5 + 32)}°F`;
}

const WX_LABELS: Record<string, string> = {
  BR: "Niebla ligera", FG: "Niebla", HZ: "Neblina", FU: "Humo",
  RA: "Lluvia", DZ: "Llovizna", SN: "Nieve", SG: "Nieve granulada",
  IC: "Cristales de hielo", PL: "Aguanieve", GR: "Granizo", GS: "Granizo fino",
  TS: "Tormenta eléctrica", SH: "Chubascos", FZ: "Engelante",
  SA: "Arena", DU: "Polvo", PO: "Torbellino", SQ: "Turbonada",
  FC: "Nube embudo", SS: "Tormenta de arena", DS: "Tormenta de polvo", VA: "Ceniza volcánica",
};

function translateWx(wx: string): string {
  const upper = wx.toUpperCase().trim();
  for (const [code, label] of Object.entries(WX_LABELS)) {
    if (upper.includes(code)) return label;
  }
  return upper;
}

function validWx(wx: string | null | undefined): string | null {
  if (!wx || wx === "M" || wx.trim() === "") return null;
  return wx.trim();
}

function buildCondition(d: WeatherData): string {
  const parts: string[] = [];
  const wx = validWx(d.wx_codes);
  if (wx) parts.push(translateWx(wx));
  if (d.precip_flag) parts.push("Precipitación");
  if (d.low_visibility) parts.push("Baja visibilidad");
  if (d.strong_wind) parts.push("Vientos fuertes");
  return parts.length > 0 ? parts.join(" · ") : "Despejado";
}

function buildMetar(d: WeatherData): string {
  const dt = new Date(d.valid_utc.endsWith("Z") ? d.valid_utc : d.valid_utc + "Z");
  const day = dt.getUTCDate().toString().padStart(2, "0");
  const hhmm = `${dt.getUTCHours().toString().padStart(2, "0")}${dt.getUTCMinutes().toString().padStart(2, "0")}`;
  const dir = d.wind_direction?.toString().padStart(3, "0") ?? "VRB";
  const spd = d.wind_knots == null ? null : Math.round(d.wind_knots).toString().padStart(2, "0");
  const gust = d.gust_knots ? `G${Math.round(d.gust_knots).toString().padStart(2, "0")}` : "";
  const vis = d.visibility_miles != null ? `${d.visibility_miles}SM` : "";
  const wx = validWx(d.wx_codes) ?? "";
  const formatTemp = (value: number | null) => {
    if (value === null) return "//";
    const rounded = Math.round(value);
    return `${rounded < 0 ? "M" : ""}${Math.abs(rounded).toString().padStart(2, "0")}`;
  };
  const wind = spd === null ? "" : `${dir}${spd}${gust}KT`;
  const tStr = `${formatTemp(d.temperature_c)}/${formatTemp(d.dewpoint_c)}`;
  const alti = d.altimeter_inhg != null ? `A${Math.round(d.altimeter_inhg * 100)}` : "";
  return `KATL ${day}${hhmm}Z ${wind} ${vis} ${wx} ${tStr} ${alti}`.replace(/\s{2,}/g, " ").trim();
}

function conditionSeverity(d: WeatherData): "normal" | "caution" | "severe" {
  if (d.low_visibility || d.strong_wind) return "severe";
  if (d.precip_flag || validWx(d.wx_codes)) return "caution";
  return "normal";
}

export type WeatherErrorKind = "unavailable" | "server" | null;

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
export function WeatherCardView({
  data,
  errorKind,
  title = "Condiciones meteorológicas ATL",
}: {
  data: WeatherData | null;
  errorKind: WeatherErrorKind;
  title?: string;
}) {
  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="flex items-center gap-2 text-sm font-medium">
          <Cloud className="size-4 text-muted-foreground" />
          {title}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        {errorKind === "server" ? (
          <div className="flex items-center gap-2 py-4 text-sm text-risk-high">
            <AlertTriangle className="size-4 shrink-0" />
            No se pudo conectar con el servidor meteorológico.
          </div>
        ) : errorKind === "unavailable" ? (
          <p className="py-4 text-center text-sm text-muted-foreground">
            Sin datos meteorológicos disponibles aún.
          </p>
        ) : data ? (
          <>
            {/* Condition banner */}
            {conditionSeverity(data) !== "normal" && (
              <div
                className={cn(
                  "flex items-center gap-2 rounded-md px-3 py-2 text-xs font-medium",
                  conditionSeverity(data) === "severe"
                    ? "bg-risk-high/10 text-risk-high"
                    : "bg-risk-medium/10 text-risk-medium",
                )}
              >
                <span className={cn(
                  "size-1.5 rounded-full",
                  conditionSeverity(data) === "severe" ? "bg-risk-high" : "bg-risk-medium",
                )} />
                {buildCondition(data)}
              </div>
            )}

            {/* Stats grid */}
            <div className="grid grid-cols-3 gap-2">
              <WeatherStat
                icon={<Thermometer className="size-3.5" />}
                label="Temp"
                value={toF(data.temperature_c)}
              />
              <WeatherStat
                icon={<Wind className="size-3.5" />}
                label="Viento"
                value={data.wind_knots === null ? "—" : `${Math.round(data.wind_knots)} kt`}
                alert={data.strong_wind}
              />
              <WeatherStat
                icon={<Eye className="size-3.5" />}
                label="Visib."
                value={data.visibility_miles != null ? `${data.visibility_miles} SM` : "—"}
                alert={data.low_visibility}
              />
            </div>

            {conditionSeverity(data) === "normal" && (
              <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
                <span className="size-1.5 rounded-full bg-risk-low" />
                Despejado
              </div>
            )}

            {/* METAR */}
            <div className="space-y-1">
              <div className="text-[10px] text-muted-foreground">METAR</div>
              <code className="block rounded bg-muted px-2 py-1.5 font-mono text-[11px] leading-relaxed text-muted-foreground">
                {buildMetar(data)}
              </code>
            </div>

            <div className="text-[11px] text-muted-foreground">
              Actualizado:{" "}
              {new Date(
                data.valid_utc.endsWith("Z") ? data.valid_utc : data.valid_utc + "Z",
              ).toLocaleString("es-AR", {
                timeZone: "UTC",
                day: "2-digit",
                month: "2-digit",
                hour: "2-digit",
                minute: "2-digit",
                hour12: false,
              })}{" "}
              UTC
            </div>
          </>
        ) : null}
      </CardContent>
    </Card>
  );
}

function WeatherStat({
  icon,
  label,
  value,
  alert = false,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  alert?: boolean;
}) {
  return (
    <div className={cn(
      "rounded-md border p-2 transition-colors",
      alert ? "border-risk-high/30 bg-risk-high/5" : "bg-muted/30",
    )}>
      <div className={cn(
        "flex items-center gap-1 text-[10px]",
