    scheduled_in_utc: "2026-08-09T12:00:00Z",
    estimated_out_utc: "2026-08-09T10:00:00Z",
    estimated_in_utc: "2026-08-09T12:00:00Z",
    actual_out_utc: null,
    actual_off_utc: null,
    actual_on_utc: null,
    actual_in_utc: null,
    aircraft_type: "A320",
    risk: "medium",
    delay_probability: 0.22,
    predicted_delay: 0,
    predicted_at_utc: "2026-08-09T09:45:00Z",
    has_actual: false,
    arr_delay_min: null,
    departure_delay_min: null,
    ...overrides,
  };
}

describe("flightToTrack", () => {
  it("keeps an undeparted flight at its origin", () => {
    const track = flightToTrack(flight(), Date.parse("2026-08-09T11:00:00Z"));
    expect(track).not.toBeNull();
    expect(track?.isDeparted).toBe(false);
    expect(track?.progress).toBe(0);
    expect(track?.currentLat).toBeCloseTo(track?.originLat ?? 0);
    expect(track?.currentLng).toBeCloseTo(track?.originLng ?? 0);
  });

  it("interpolates progress only after a confirmed departure", () => {
    const track = flightToTrack(
      flight({ actual_out_utc: "2026-08-09T10:00:00Z", departure_delay_min: 0 }),
      Date.parse("2026-08-09T11:00:00Z"),
    );
    expect(track?.progress).toBeCloseTo(0.5);
  });

  it("uses wheels-up when the provider has no gate-out timestamp", () => {
    const track = flightToTrack(
      flight({ actual_off_utc: "2026-08-09T10:10:00Z", departure_delay_min: 10 }),
      Date.parse("2026-08-09T11:05:00Z"),
    );
    expect(track?.isDeparted).toBe(true);
    expect(track?.progress).toBeCloseTo(0.5);
  });

  // El backend serializa con offset ("+00:00"), no con sufijo "Z". Estos
  // fixtures replican ese formato: con la implementación anterior, que
  // concatenaba "Z", cada timestamp quedaba inválido y el mapa mostraba 0
  // vuelos aun teniendo cientos en la respuesta.
  it("parses timestamps serialised with a UTC offset instead of Z", () => {
    const track = flightToTrack(
      flight({
        scheduled_out_utc: "2026-08-09T10:00:00+00:00",
        scheduled_in_utc: "2026-08-09T12:00:00+00:00",
        estimated_out_utc: "2026-08-09T10:00:00+00:00",
        estimated_in_utc: "2026-08-09T12:00:00+00:00",
        actual_out_utc: "2026-08-09T10:00:00+00:00",
        departure_delay_min: 0,
      }),
      Date.parse("2026-08-09T11:00:00Z"),
    );
    expect(track).not.toBeNull();
    expect(track?.progress).toBeCloseTo(0.5);
  });
});

"use client";

import * as React from "react";

import { api, type Flight } from "@/lib/api";

type FlightsState = {
  flights: Flight[];
  loading: boolean;
  isRefreshing: boolean;
  error: string | null;
  lastUpdated: Date | null;
};

const INITIAL_STATE: FlightsState = {
  flights: [],
  loading: true,
  isRefreshing: false,
  error: null,
  lastUpdated: null,
};

export function useFlights(refreshIntervalMs = 60_000) {
  const [state, setState] = React.useState<FlightsState>(INITIAL_STATE);

  const reload = React.useCallback(async () => {
    setState((current) => ({ ...current, isRefreshing: current.flights.length > 0 }));
    try {
      const flights = await api.flights();
      setState({
        flights,
        loading: false,
        isRefreshing: false,
        error: null,
        lastUpdated: new Date(),
      });
    } catch (error) {
      setState((current) => ({
        ...current,
        loading: false,
        isRefreshing: false,
        error: error instanceof Error ? error.message : "No se pudieron cargar los vuelos.",
      }));
    }
  }, []);

  React.useEffect(() => {
    let active = true;

    async function load() {
      try {
        const flights = await api.flights();
        if (!active) return;
        setState({
          flights,
          loading: false,
          isRefreshing: false,
          error: null,
          lastUpdated: new Date(),
        });
      } catch (error) {
        if (!active) return;
        setState((current) => ({
          ...current,
          loading: false,
          isRefreshing: false,
          error: error instanceof Error ? error.message : "No se pudieron cargar los vuelos.",
        }));
      }
    }

    void load();
    const interval = window.setInterval(load, refreshIntervalMs);
    return () => {
      active = false;
      window.clearInterval(interval);
    };
  }, [refreshIntervalMs]);

  return { ...state, reload };
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const subscribe = React.useCallback((onStoreChange: () => void) => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    mql.addEventListener("change", onStoreChange)
    return () => mql.removeEventListener("change", onStoreChange)
  }, [])

  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches,
    () => false,
  )
}

"use client";

import * as React from "react";
import { toUTCDate, type Flight } from "@/lib/api";
import { AIRPORTS, greatCirclePoint, initialBearing } from "@/lib/geo";
import { useFlights } from "@/hooks/use-flights";

export type MapTrack = {
  id: string;
  flightNumber: string;
  airline: string;
  origin: string;
  destination: string;
  risk: "high" | "medium" | "low";
  delayProbability: number;
  bearing: number;
  currentLat: number;
  currentLng: number;
  originLat: number;
  originLng: number;
  destLat: number;
  destLng: number;
  progress: number;
  isDeparted: boolean;
  minutesToDep: number;
};

function toMs(iso: string | null | undefined): number | null {
  if (!iso) return null;
  // El backend devuelve offsets ("...+00:00"), no sufijo "Z". Concatenar "Z"
  // producía "...+00:00Z" — fecha inválida — y descartaba todos los vuelos.
  const ms = toUTCDate(iso).getTime();
  return Number.isNaN(ms) ? null : ms;
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
export function flightToTrack(f: Flight, now: number): MapTrack | null {
  const o = AIRPORTS[f.origin];
  const d = AIRPORTS[f.destination];
  if (!o || !d) return null;

  const depMs = toMs(f.actual_out_utc) ?? toMs(f.actual_off_utc)
    ?? toMs(f.estimated_out_utc) ?? toMs(f.scheduled_out_utc);
  const arrMs = toMs(f.actual_in_utc) ?? toMs(f.actual_on_utc)
    ?? toMs(f.estimated_in_utc) ?? toMs(f.scheduled_in_utc);
  if (!depMs || !arrMs || arrMs <= depMs) return null;

  // progress: 0 = at origin, 1 = at destination
  const isDeparted = f.actual_out_utc !== null
    || f.actual_off_utc !== null
    || f.departure_delay_min !== null;
  let progress = isDeparted ? (now - depMs) / (arrMs - depMs) : 0;
  // show planes up to 60min before departure (pre-dep as dot at origin) through landing
  const minProgress = -60 / ((arrMs - depMs) / 60_000);
  if (progress < minProgress || progress > 1.02) return null;
  progress = Math.max(0, Math.min(1, progress));

  const pos = greatCirclePoint(o, d, progress);
  const bearing = initialBearing(pos, d);

  const estOutMs = toMs(f.estimated_out_utc) ?? toMs(f.scheduled_out_utc);
  const minutesToDep = estOutMs !== null ? (estOutMs - now) / 60_000 : 0;

  return {
    id: f.fa_flight_id,
    flightNumber: f.flight_number,
    airline: f.airline_code,
    origin: f.origin,
    destination: f.destination,
    risk: f.risk,
    delayProbability: f.delay_probability,
    bearing,
    currentLat: pos.lat,
    currentLng: pos.lng,
    originLat: o.lat,
    originLng: o.lng,
    destLat: d.lat,
    destLng: d.lng,
    progress,
    isDeparted,
    minutesToDep,
  };
}

export function flightsToTracks(flights: Flight[], now = Date.now()) {
  return flights
    .map((flight) => flightToTrack(flight, now))
    .filter((track): track is MapTrack => track !== null);
}

export function useRealFlightTracks() {
  const result = useFlights();
  const tracks = React.useMemo(
    () => flightsToTracks(result.flights),
    [result.flights],
  );
  return { ...result, tracks };
}

"use client";

import * as React from "react";
import type { WeatherStation } from "@/lib/mock-data";
import type { AwcMetar } from "@/lib/weather-api";
import { appUrl } from "@/lib/mobile-env";

export type WeatherApiResponse = {
  stations: WeatherStation[];
  atlRaw: string | null;
  rawPayload: AwcMetar[];
  requestUrl: string;
  fetchedAt: string;
  elapsedMs: number;
};

export type WeatherApiErrorResponse = {
  error: string;
  requestUrl: string;
  elapsedMs: number;
};

type State = {
  status: "idle" | "loading" | "success" | "error";
  data: WeatherApiResponse | null;
  error: string | null;
};

export function useWeatherStations(ids?: string[]) {
  const [state, setState] = React.useState<State>({
    status: "loading",
    data: null,
    error: null,
  });

  // `/api/weather` es un route handler de este mismo Next: agrega los METARs de
  // aviationweather.gov, que no manda cabeceras CORS y por eso no se puede
  // llamar desde el WebView. En la web `appUrl` es identidad y esto queda igual
  // que antes; en el bundle nativo lo apunta al deploy, donde el handler sigue
  // corriendo.
  const url = ids && ids.length > 0
    ? appUrl(`/api/weather?ids=${ids.join(",")}`)
    : appUrl("/api/weather");

  const load = React.useCallback(async () => {
    setState((s) => ({ ...s, status: "loading", error: null }));
    try {
      const res = await fetch(url, {
        cache: "no-store",
        headers: { Accept: "application/json" },
      });
      if (!res.ok) {
        const err = (await res.json().catch(() => ({}))) as Partial<WeatherApiErrorResponse>;
        throw new Error(err.error ?? `Proxy devolvió ${res.status} ${res.statusText}`);
      }
      const data = (await res.json()) as WeatherApiResponse;
      setState({ status: "success", data, error: null });
    } catch (e) {
      setState({ status: "error", data: null, error: e instanceof Error ? e.message : String(e) });
    }
  }, [url]);

  React.useEffect(() => {
    let active = true;
    fetch(url, { cache: "no-store", headers: { Accept: "application/json" } })
      .then(async (res) => {
        if (!res.ok) {
          const err = (await res.json().catch(() => ({}))) as Partial<WeatherApiErrorResponse>;
          throw new Error(err.error ?? `Proxy devolvió ${res.status} ${res.statusText}`);
        }
        return res.json() as Promise<WeatherApiResponse>;
      })
      .then((data) => { if (active) setState({ status: "success", data, error: null }); })
      .catch((error: unknown) => {
        if (!active) return;
        setState({ status: "error", data: null, error: error instanceof Error ? error.message : String(error) });
      });
    return () => { active = false; };
  }, [url]);

  return { ...state, reload: load };
}

