async function getAuthHeaders(): Promise<HeadersInit> {
  if (typeof window !== "undefined") {
    // Web: la cookie HttpOnly viaja sola y el BFF pone el Authorization.
    if (!IS_BUNDLED) return {};
    // Bundle nativo: no hay BFF ni cookie que cruce de origen.
    const { loadToken } = await import("@/lib/native/session");
    const token = await loadToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  try {
    const { cookies } = await import("next/headers");
    const store = await cookies();
    const token = store.get("auth-token")?.value;
    return token ? { Authorization: `Bearer ${token}` } : {};
  } catch {
    return {};
  }
}

/** Respuesta de GET /admin/db-stats. Los conteos varían según qué tablas existan. */
export type DbStats = {
  db_size_mb: number;
  table_counts: Record<string, number>;
  prediction_dates: { first: string | null; last: string | null };
};

export class ApiError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message);
    this.name = "ApiError";
  }
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
async function get<T>(path: string, options?: RequestInit): Promise<T> {
  const authHdrs = await getAuthHeaders();
  const base = typeof window === "undefined" ? SERVER_BASE : CLIENT_BASE;
  const res = await fetch(`${base}${path}`, {
    cache: "no-store",
    signal: options?.signal ?? AbortSignal.timeout(15_000),
    ...options,
    headers: { ...authHdrs, ...(options?.headers ?? {}) },
  });
  if (res.status === 401) {
    if (typeof window !== "undefined") {
      // En la web el BFF ya vació la cookie al ver el 401 del backend. En el
      // bundle no hay BFF: si el token expirado se queda guardado, el próximo
      // arranque lo vuelve a mandar y la app entra en un ciclo de 401.
      if (IS_BUNDLED) {
        const { clearToken } = await import("@/lib/native/session");
        await clearToken();
      }
      if (!window.location.pathname.startsWith("/login")) {
        window.location.replace(appPath("/login"));
      }
    }
    throw new ApiError(401, "La sesión venció. Volvé a ingresar.");
  }
  if (!res.ok) {
    const payload = (await res.json().catch(() => null)) as
      | { detail?: string; error?: string }
      | null;
    throw new ApiError(
      res.status,
      payload?.detail ?? payload?.error ?? `API ${path} → ${res.status}`,
    );
  }
  if (res.status === 204) return undefined as unknown as T;
  return res.json() as Promise<T>;
}

/** Usuario de la sesión actual, validado contra el backend. */
export async function apiMe(): Promise<SessionUser> {
  const payload = await get<Partial<SessionUser> & { user_type?: unknown }>("/auth/me");
  if (typeof payload.username !== "string" || !isRole(payload.role)) {
    throw new ApiError(502, "No se pudo validar la sesión");
  }
  // `userType` decide el perfil (viajero u operaciones) y si hace falta pasar
  // por el onboarding. En la web lo lee getVerifiedSession() en el servidor;
  // en el bundle esta es la única fuente, así que no se puede descartar.
  return {
    username: payload.username,
    role: payload.role,
    userType: isUserType(payload.user_type) ? payload.user_type : null,
  };
}

export async function apiLogin(username: string, password: string) {
  // El bundle nativo no tiene el BFF: hace los dos saltos que el route handler
  // hacía del lado del servidor (login y luego /auth/me) y se queda con el
  // token en almacenamiento nativo en vez de en una cookie HttpOnly.
  if (IS_BUNDLED) return nativeLogin(username, password);

  const res = await fetch("/api/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password }),
    signal: AbortSignal.timeout(10_000),
  });
  const payload = (await res.json().catch(() => null)) as
    | (Partial<SessionUser> & { detail?: string })
    | null;
  if (!res.ok) {
    throw new ApiError(
      res.status,
      payload?.detail ?? "No se pudo iniciar sesión.",
    );
  }
  return payload as SessionUser;
}

export async function apiLoginGoogle(idToken: string) {
  if (IS_BUNDLED) return nativeExchange("/auth/google", idToken);

  const res = await fetch("/api/auth/google", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id_token: idToken }),
    signal: AbortSignal.timeout(10_000),
  });
  const payload = (await res.json().catch(() => null)) as
    | (SessionUser & { isNewUser: boolean; detail?: string })
    | null;
  if (!res.ok || !payload) {
    throw new ApiError(
      res.status,
      payload?.detail ?? "No se pudo iniciar sesión con Google.",
    );
  }
  return payload;
}

/**
 * Cambia un ID token de Firebase por la sesión propia.
 *
 * Firebase ya verificó quién es; esto convierte esa prueba en un JWT nuestro,
 * que es el que lleva el rol y el tipo de cuenta.
 */
export async function apiLoginFirebase(idToken: string) {
  if (IS_BUNDLED) return nativeExchange("/auth/firebase", idToken);

  const res = await fetch("/api/auth/firebase", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id_token: idToken }),
    signal: AbortSignal.timeout(10_000),
  });
  const payload = (await res.json().catch(() => null)) as
    | (SessionUser & { isNewUser: boolean; detail?: string })
    | null;
  if (!res.ok || !payload) {
    throw new ApiError(
      res.status,
      payload?.detail ?? "No se pudo iniciar sesión.",
    );
  }
  return payload;
}

/** Persist the B2B/B2C profile for the signed-in user. */
export async function apiSetUserType(userType: UserType) {
  // En la web la cookie viaja sola y el BFF pone el Authorization; en el
  // bundle no hay BFF, y sin este header el onboarding cobraba un 401.
  const res = await fetch(`${CLIENT_BASE}/users/me`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...(await getAuthHeaders()) },
    body: JSON.stringify({ user_type: userType }),
    signal: AbortSignal.timeout(10_000),
  });
  if (!res.ok) {
    const payload = (await res.json().catch(() => null)) as { detail?: string } | null;
    throw new ApiError(
      res.status,
      payload?.detail ?? "No se pudo guardar el perfil.",
    );
  }
}

async function nativeLogin(
  username: string,
  password: string,
): Promise<SessionUser> {
  const { saveToken, clearToken } = await import("@/lib/native/session");

  let res: Response;
  try {
    res = await fetch(`${API_ORIGIN}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password }),
      signal: AbortSignal.timeout(10_000),
    });
  } catch {
    throw new ApiError(503, "No se pudo conectar con el servidor.");
  }

  const payload = (await res.json().catch(() => null)) as
    | { access_token?: string; detail?: string }
    | null;
  if (!res.ok || !payload?.access_token) {
    throw new ApiError(
      res.status || 401,
      payload?.detail ?? "Credenciales incorrectas",
    );
  }

  await saveToken(payload.access_token);
  try {
    return await apiMe();
  } catch (cause) {
    // Un token que no sirve para leer el propio usuario no es una sesión: si
    // se queda guardado, el arranque siguiente cree que hay sesión y muestra un
    // dashboard vacío en vez del login.
    await clearToken();
    throw cause;
  }
}

/**
 * Rama del bundle de `apiLoginGoogle` / `apiLoginFirebase`.
 *
 * Hace lo que el route handler hacía del lado del servidor: cambia el ID token
 * por un JWT propio contra el FastAPI directo, se queda con el token en
 * almacenamiento nativo en vez de en una cookie HttpOnly, y lee /auth/me para
 * devolver la misma forma que devuelve el BFF. `isNewUser` se deriva igual que
 * allá: lo dice el backend, o no hay tipo de cuenta todavía.
 */
// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
async function nativeExchange(
  path: "/auth/google" | "/auth/firebase",
  idToken: string,
): Promise<SessionUser & { isNewUser: boolean }> {
  const { saveToken, clearToken } = await import("@/lib/native/session");

  let res: Response;
  try {
    res = await fetch(`${API_ORIGIN}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id_token: idToken }),
      signal: AbortSignal.timeout(10_000),
    });
  } catch {
    throw new ApiError(503, "No se pudo conectar con el servidor.");
  }

  const payload = (await res.json().catch(() => null)) as
    | { access_token?: string; user_type?: unknown; is_new_user?: boolean; detail?: string }
    | null;
  if (!res.ok || !payload?.access_token) {
    throw new ApiError(
      res.status || 401,
      payload?.detail ?? "No se pudo iniciar sesión.",
    );
  }

  await saveToken(payload.access_token);
  try {
    const user = await apiMe();
    const userType = isUserType(payload.user_type) ? payload.user_type : user.userType ?? null;
    return {
      ...user,
      userType,
      isNewUser: payload.is_new_user === true || userType === null,
    };
  } catch (cause) {
    // Igual que en nativeLogin: un token con el que no se puede leer el propio
    // usuario no es una sesión, y guardado haría que el próximo arranque crea
    // que sí la hay.
    await clearToken();
    throw cause;
  }
}

/**
 * Baja de la propia cuenta. Las tiendas la exigen dentro de la app (App Store
 * 5.1.1, Play "Account deletion"): el backend borra la fila y la cuenta de
 * Firebase, y acá se cierra la sesión local para que no quede un token de
 * alguien que ya no existe. Un 404 cuenta como éxito: la cuenta ya no está.
 */
export async function apiDeleteAccount() {
  const res = await fetch(`${CLIENT_BASE}/users/me`, {
    method: "DELETE",
    headers: await getAuthHeaders(),
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok && res.status !== 404) {
    const payload = (await res.json().catch(() => null)) as { detail?: string } | null;
    throw new ApiError(res.status, payload?.detail ?? "No se pudo eliminar la cuenta.");
  }
  await apiLogout().catch(() => undefined);
}

export async function apiLogout() {
  if (IS_BUNDLED) {
    const { clearToken } = await import("@/lib/native/session");
    await clearToken();
    return;
  }

  const response = await fetch("/api/auth/logout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) throw new ApiError(response.status, "No se pudo cerrar la sesión");
}

