export type MotivoViajero = {
  texto: string;
  /** `true` si empuja hacia la demora. */
  enContra: boolean;
  /** Peso relativo dentro de los motivos mostrados, de 0 a 1. */
  peso: number;
  /** `true` cuando no hubo frase propia y se usó la etiqueta del backend. */
  generico: boolean;
};

/**
 * Convierte un factor sin frase propia en algo mostrable.
 *
 * Existe para que ninguna feature desaparezca. Si mañana el modelo agrega una
 * variable nueva, el viajero va a ver su etiqueta técnica —fea, pero cierta—
 * en vez de una lista de motivos a la que le falta el principal.
 */
function respaldo(f: ShapFactor, enContra: boolean): string {
  const etiqueta = (f.label || f.feature).trim();
  return enContra
    ? `${etiqueta}: empuja hacia la demora`
    : `${etiqueta}: juega a favor`;
}

/**
 * Los motivos que vale mostrarle a un pasajero, del que más pesa al que menos.
 *
 * `maximo` recorta porque una lista de quince razones no es una explicación,
 * es un volcado. Tres o cuatro alcanzan para entender de qué se trata.
 */
export function motivosParaViajero(
  factores: ShapFactor[] | undefined,
  maximo = 4,
): MotivoViajero[] {
  if (!factores || factores.length === 0) return [];

  const traducidos = factores.map((f) => {
    // `direction` viene explícito del backend; no se infiere del signo de
    // `contribution`, que según el endpoint puede llegar ya en valor absoluto
    // y dejaría todos los motivos del mismo lado.
    const enContra = f.direction === "positive";
    const lectura = MOTIVOS[f.feature];
    return {
      texto: lectura ? (enContra ? lectura.sube : lectura.baja) : respaldo(f, enContra),
      enContra,
      generico: !lectura,
      magnitud: Math.abs(f.contribution),
    };
  });

  traducidos.sort((a, b) => b.magnitud - a.magnitud);

  // Se eliminan los duplicados por texto: varias ventanas de la misma señal
  // —origen a 1 h, 6 h y 24 h, o seno y coseno de la hora— se traducen igual,
  // y repetir la misma frase hace ver como ruido lo que es una sola causa. Se
  // conserva la de mayor magnitud porque la lista ya está ordenada.
  const vistos = new Set<string>();
  const unicos = traducidos.filter((m) => {
    if (vistos.has(m.texto)) return false;
    vistos.add(m.texto);
    return true;
  });

  const recortados = unicos.slice(0, maximo);
  const mayor = recortados[0]?.magnitud ?? 1;
  return recortados.map((m) => ({
    texto: m.texto,
    enContra: m.enContra,
    generico: m.generico,
    peso: mayor > 0 ? m.magnitud / mayor : 0,
  }));
}

/** Una frase sobre la probabilidad, sin número. */
export function veredicto(probabilidad: number): {
  titulo: string;
  detalle: string;
} {
  if (probabilidad >= 0.5) {
    return {
      titulo: "Es probable que se demore",
      detalle: "Conviene tenerlo en cuenta si tenés una conexión ajustada.",
    };
  }
  if (probabilidad >= 0.2) {
    return {
      titulo: "Puede demorarse",
      detalle: "No es lo más probable, pero hay señales de riesgo.",
    };
  }
  return {
    titulo: "Debería salir en horario",
    detalle: "No vemos señales de demora para este vuelo.",
  };
}

/**
 * Dos señales del arranque nativo que conviene no confundir, porque tienen
 * ventanas de tiempo distintas:
 *
 *  1. `notifyAppReady()` — confirmarle al plugin de OTA que este bundle arrancó. Si no
 *     llega dentro de `appReadyTimeout` (10 s en `capacitor.config.ios.ts`),
 *     el plugin asume que el bundle nuevo rompió el arranque y revierte solo al
 *     anterior. Es el seguro contra un OTA malo, y lo que prueba es que el JS
 *     carga y React monta: eso es lo que un bundle roto no consigue. NO debe
 *     esperar a la sesión —`/auth/me` contra un Cloud Run frío puede tardar
 *     más que la ventana— porque entonces un backend lento se leería como un
 *     bundle roto y el plugin desharía un OTA sano en cada arranque en frío.
 *
 *  2. `hideSplash()` — bajar el splash. Acá sí hay que esperar: el arranque del
 *     bundle tiene varios saltos (el WebView carga el index, bootea React, y
 *     recién ahí la sesión resuelve si va al dashboard o al login). Bajarlo
 *     antes muestra blanco.
 *
 * Las dos corren una sola vez por arranque y son no-op fuera del nativo.
 */

let readyNotified = false;
let splashHidden = false;

export async function notifyAppReady(): Promise<void> {
  if (readyNotified) return;
  readyNotified = true;

  const { Capacitor } = await import("@capacitor/core");
  if (!Capacitor.isNativePlatform()) return;

  try {
    const { CapacitorUpdater } = await import("@capgo/capacitor-updater");
    await CapacitorUpdater.notifyAppReady();
  } catch {
    // Sin OTA configurado el plugin no está o falla: la app igual tiene que
    // arrancar. El bundle empaquetado no depende del OTA para funcionar.
  }
}

export async function hideSplash(): Promise<void> {
  if (splashHidden) return;
  splashHidden = true;

  const { Capacitor } = await import("@capacitor/core");
  if (!Capacitor.isNativePlatform()) return;

  try {
    const { SplashScreen } = await import("@capacitor/splash-screen");
    await SplashScreen.hide();
  } catch {
    // `launchAutoHide` lo baja igual por temporizador.
  }
}

/**
 * Token de sesión en el bundle nativo.
 *
 * En la web el token vive en una cookie `HttpOnly` que JS no puede leer, y el
 * BFF `/api/backend/*` es quien la traduce a un header `Authorization`. Ese
 * diseño no sobrevive al empaquetado: el WebView corre sobre
 * `capacitor://localhost`, el BFF no viaja en el binario, y una cookie
 * `SameSite=lax` puesta por el backend en otro origen no se manda.
 *
 * Acá el token lo guarda el propio JS en `@capacitor/preferences`, que en iOS
 * escribe en `UserDefaults` del contenedor de la app —almacenamiento privado
 * del proceso, no compartido con otras apps ni legible desde el WebView de
 * otra— y sobrevive a cerrar la app.
 *
 * Es una superficie de exposición mayor que la cookie `HttpOnly` de la web: acá
 * el token SÍ es alcanzable por el JS que corre en el WebView. Es la
 * consecuencia inevitable de sacar el servidor del medio, y el motivo de que la
 * web no cambie: sigue con la cookie.
 *
 * `@capacitor/preferences` se importa con `import()` dinámico a propósito. Este
 * módulo lo alcanzan builds que no son nativos (el árbol de tipos de la web),
 * y una importación estática metería el plugin en el bundle del navegador.
 */

const TOKEN_KEY = "ontimeai.auth.token";

/**
 * Cache en memoria del token.
 *
 * `undefined` = todavía no se leyó del almacenamiento; `null` = se leyó y no
 * hay sesión. La distinción importa: sin ella, cada request pagaría un salto al
 * puente nativo, que es asíncrono y en el arranque compite con el primer render.
 */
let cached: string | null | undefined;

/**
 * OJO — el plugin NO se puede devolver desde una función async ni pasar por un
 * `await`, y esa restricción no es un detalle de estilo.
 *
 * `Preferences` es un Proxy que convierte el acceso a CUALQUIER propiedad en
 * una llamada al plugin nativo. Cuando una promesa adopta un valor, lo primero
 * que hace es leerle `.then` para ver si es un thenable: el Proxy contesta con
 * una función, la maquinaria de promesas la llama creyendo que encadena, y la
 * llamada viaja al puente como un método "then" que no existe.
 *
 * El síntoma es peor que un error: además de tirar
 * `"Preferences.then()" is not implemented`, la promesa queda sin resolver
 * nunca. Una app que arranca contra esto se queda en la pantalla de carga para
 * siempre, sin nada que lo explique.
 *
 * Por eso el import va adentro de cada función y el plugin se usa en el lugar:
 * lo que se awaitea es `Preferences.get(...)`, que sí devuelve una promesa de
 * verdad, y nunca `Preferences`.
 */

/** Token actual, leyéndolo del almacenamiento nativo la primera vez. */
export async function loadToken(): Promise<string | null> {
  if (cached !== undefined) return cached;
  try {
    const { Preferences } = await import("@capacitor/preferences");
    const { value } = await Preferences.get({ key: TOKEN_KEY });
    cached = value ?? null;
  } catch {
    // Sin puente nativo (por ejemplo, el bundle abierto en un navegador de
    // escritorio para depurar) no hay sesión persistida, no un error fatal.
    cached = null;
  }
  return cached;
}

export async function saveToken(token: string): Promise<void> {
  cached = token;
  try {
    const { Preferences } = await import("@capacitor/preferences");
    await Preferences.set({ key: TOKEN_KEY, value: token });
  } catch {
    // El token queda en memoria: la sesión anda hasta cerrar la app.
  }
}

export async function clearToken(): Promise<void> {
  cached = null;
  try {
    const { Preferences } = await import("@capacitor/preferences");
    await Preferences.remove({ key: TOKEN_KEY });
  } catch {
    // Ya está limpio en memoria, que es lo que corta la sesión en curso.
  }
}

import { toUTCDate, type Flight } from "@/lib/api";

/**
 * Impacto operacional derivado de los vuelos activos (issue #6).
 *
 * Nota importante sobre `predicted_delay`: es binario (0/1), no minutos. El
 * modelo v9 es un clasificador sobre `arr_delay_min > 15`, así que no produce
 * una magnitud de demora y sumarlo daría un conteo de vuelos, no tiempo.
 *
 * Para llegar a minutos se combinan dos cantidades que sí son observables:
 *
 *   1. La cantidad esperada de demoras, como suma de las probabilidades de
 *      los vuelos que todavía no despegaron. Es la esperanza de una suma de
 *      Bernoullis, no una heurística.
 *   2. La demora mediana de los vuelos que ya aterrizaron demorados hoy,
 *      medida sobre los actuals del propio dataset.
 *
 * El producto es una estimación, y como tal se rotula en la UI. Se usa mediana
 * y no media porque la distribución de demoras tiene cola larga: un vuelo con
 * 6 horas de retraso desplaza la media y exagera el total.
 */

/** Umbral DOT/BTS: un vuelo está demorado si llega 15+ minutos tarde. */
const DELAY_THRESHOLD_MIN = 15;

/** Ventana en la que todavía se puede reorganizar puertas y tripulaciones. */
export const ACTION_WINDOW_MIN = 120;

export type OperationalImpact = {
  /** Vuelos con predicción activa que aún no despegaron. */
  notDeparted: number;
  /** Suma de probabilidades sobre esos vuelos: demoras esperadas. */
  expectedDelays: number;
  /** Demora mediana observada hoy entre los vuelos que llegaron tarde. */
  medianDelayMin: number | null;
  /** expectedDelays × medianDelayMin. Null si todavía no hay actuals. */
  anticipatedMinutes: number | null;
  /** Cuántos actuals sostienen la mediana. */
  actualsSampleSize: number;
  /** Riesgo alto, sin despegar, saliendo dentro de la ventana de acción. */
  actionableFlights: number;
};

function hasDeparted(f: Flight): boolean {
  return f.actual_out_utc !== null || f.actual_off_utc !== null;
}

function median(values: number[]): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

export function computeOperationalImpact(
  flights: Flight[],
  now: number,
): OperationalImpact {
  const pending = flights.filter((f) => !hasDeparted(f));

  const expectedDelays = pending.reduce(
    (sum, f) => sum + (f.delay_probability ?? 0),
    0,
  );

  const observedDelays = flights
    .filter(
      (f) =>
        f.has_actual &&
        f.arr_delay_min !== null &&
        f.arr_delay_min > DELAY_THRESHOLD_MIN,
    )
    .map((f) => f.arr_delay_min as number);

  const medianDelayMin = median(observedDelays);

  const actionableFlights = pending.filter((f) => {
    if (f.risk !== "high") return false;
    const departure = f.estimated_out_utc || f.scheduled_out_utc;
    if (!departure) return false;
    const minutesAway = (toUTCDate(departure).getTime() - now) / 60_000;
    return minutesAway >= 0 && minutesAway <= ACTION_WINDOW_MIN;
  }).length;

  return {
    notDeparted: pending.length,
    expectedDelays,
    medianDelayMin,
    anticipatedMinutes:
      medianDelayMin === null ? null : expectedDelays * medianDelayMin,
    actualsSampleSize: observedDelays.length,
    actionableFlights,
  };
}

/** 2545 → "42 h 25 m". Los totales diarios en minutos crudos no se leen. */
export function formatMinutes(total: number): string {
  const rounded = Math.round(total);
  const hours = Math.floor(rounded / 60);
  const minutes = rounded % 60;
  if (hours === 0) return `${minutes} min`;
  return `${hours} h ${String(minutes).padStart(2, "0")} m`;
}

/**
 * La geometría de la cortina de pista, en un solo lugar.
 *
 * El componente, las posiciones de reposo para "reducir movimiento" y el
 * polígono del asfalto salen todos de esta curva. Si vivieran por separado
 * se desalinearían: las luces de borde quedarían flotando sobre el asfalto en
 * vez de apoyadas en el borde, que fue justo el primer error de esta pantalla.
 *
 * ## Por qué no es perspectiva real
 *
 * Una proyección de cámara honesta da `y = horizonte + k/Z`, y con la cámara
 * a la altura de una cabina casi todo el recorrido visible pasa en el último
 * 10% del trayecto: tres segundos quietos y un borrón. Eso es exactamente lo
 * que se ve desde un avión, y es exactamente lo que no sirve para una espera
 * de dos segundos.
 *
 * Así que la curva es cúbica en vez de hiperbólica: misma lectura de
 * profundidad —lo lejano chico y lento, lo cercano grande y rápido— con el
 * movimiento repartido de forma que siempre haya algo cruzando la pantalla.
 *
 * El precio es que el borde del asfalto, que en una proyección real sería una
 * recta, acá es una curva suave. Nadie lo nota; que las luces no coincidan con
 * el borde se nota al instante.
 */

/** Dónde está el horizonte, en porcentaje de la altura de la pantalla. */
export const HORIZONTE_PCT = 54;

/** Cuánto baja un tramo desde el horizonte al salir de cuadro, en vh. */
const RECORRIDO_VH = 50;

/** Escala mínima: a qué tamaño aparece un tramo en el punto de fuga. */
const ESCALA_MINIMA = 0.03;

/** Separación lateral de las luces de borde a escala 1, en vw. */
export const BORDE_VW = 33;

/** El asfalto asoma un poco por fuera de las luces, como en una pista real. */
const ASFALTO_VW = 36;

/** Lo que tarda un tramo en recorrer la pista entera. */
export const CICLO_MS = 2200;

/** Cuántos tramos hay a la vista. */
export const TRAMOS = 8;

export type PuntoDePista = {
  /** Cuánto baja desde el horizonte, en vh. */
  y: number;
  /** Factor de escala del tramo. */
  escala: number;
};

/**
 * La curva. `avance` va de 0 (punto de fuga) a 1 (saliendo de cuadro).
 *
 * Los exponentes no son iguales a propósito: la posición crece más rápido que
 * el tamaño, que es lo que hace que lo cercano se sienta cercano sin que los
 * tramos del fondo queden invisiblemente chicos.
 */
export function puntoDePista(avance: number): PuntoDePista {
  const a = Math.min(Math.max(avance, 0), 1);
  return {
    y: RECORRIDO_VH * a ** 3,
    escala: ESCALA_MINIMA + (1 - ESCALA_MINIMA) * a ** 2.8,
  };
}

export type Tramo = {
  /** Para la key de React. */
  indice: number;
  /** Posición de reposo, la que se usa con "reducir movimiento" activado. */
  y: number;
  escala: number;
  /**
   * Retardo NEGATIVO: arranca el ciclo por la mitad. Sin esto los dos primeros
   * segundos son tramos goteando de uno en uno desde el horizonte, y la espera
   * entera se va en poblar la pista.
   */
  retrasoMs: number;
};

/** Los tramos, repartidos a lo largo del ciclo. */
export function tramosDePista(cantidad = TRAMOS): Tramo[] {
  return Array.from({ length: cantidad }, (_, i) => {
    const avance = (i + 1) / cantidad;
    const { y, escala } = puntoDePista(avance);
    return { indice: i, y, escala, retrasoMs: -Math.round(CICLO_MS * avance) };
  });
}

/**
 * El polígono del asfalto, en coordenadas del `viewBox` 100 × 100.
 *
 * Se muestrea la misma curva que mueve los tramos, así que el borde pasa por
 * donde pasan las luces. Con `preserveAspectRatio="none"` una unidad de x es
 * 1vw y una de y es 1vh, que es lo que deja comparar con `BORDE_VW`.
 */
export function bordesDelAsfalto(muestras = 12): string {
  const derecho: string[] = [];
  const izquierdo: string[] = [];
  for (let i = 0; i <= muestras; i++) {
    const { y, escala } = puntoDePista(i / muestras);
    const alto = HORIZONTE_PCT + y;
    const ancho = ASFALTO_VW * escala;
    derecho.push(`${(50 + ancho).toFixed(2)},${alto.toFixed(2)}`);
    izquierdo.push(`${(50 - ancho).toFixed(2)},${alto.toFixed(2)}`);
  }
  return [...derecho, ...izquierdo.reverse()].join(" ");
}

/** Los destellos secuenciados del eje, los que suben hacia el umbral. */
export const DESTELLOS = Array.from({ length: 7 }, (_, i) => {
  const avance = 0.05 + i * 0.042;
  const { y, escala } = puntoDePista(avance);
  return {
    indice: i,
    y,
    escala,
    // Corre de lejos a cerca: el "conejo" de un ALSF-2 visto desde el aire.
    retrasoMs: Math.round(i * 55),
  };
});

"use client";

import { useCallback, useSyncExternalStore } from "react";

/**
 * Recuerda qué secciones quedaron expandidas, por dispositivo.
 *
 * Va en `localStorage` y no en las preferencias del backend a propósito. Es
 * estado de interfaz, no del usuario: se quiere la vista densa en el teléfono
 * y la expandida en la notebook, y guardarlo en el servidor forzaría la misma
 * densidad en los dos. Además evita una ida y vuelta en cada clic.
 *
 * Se lee con `useSyncExternalStore` y no con un efecto porque el servidor
 * dibuja el valor por defecto y el cliente el guardado: sin esto hay desajuste
 * de hidratación, y resolverlo con `setState` dentro de un efecto es
 * exactamente lo que el lint rechaza con `set-state-in-effect`.
 */
const CLAVE = "ontimeai-secciones";

type Estado = Record<string, boolean>;

let memoria: Estado | null = null;
const oyentes = new Set<() => void>();

export function leerEstado(): Estado {
  if (memoria) return memoria;
  try {
    const crudo = window.localStorage.getItem(CLAVE);
    memoria = crudo ? (JSON.parse(crudo) as Estado) : {};
  } catch {
    // Ventana privada, almacenamiento bloqueado o JSON roto. Se sigue con los
    // valores por defecto: recordar la densidad no vale romper la pantalla.
    memoria = {};
  }
  return memoria;
}

export function guardarEstado(estado: Estado) {
  memoria = estado;
  try {
    window.localStorage.setItem(CLAVE, JSON.stringify(estado));
  } catch {
    // Ídem: el estado sigue vivo en memoria durante la sesión.
  }
  for (const avisar of oyentes) avisar();
}

export function suscribir(avisar: () => void) {
  oyentes.add(avisar);
  return () => {
    oyentes.delete(avisar);
  };
}

/**
 * Estado de apertura de una sección, recordado entre visitas.
 *
 * `clave` identifica la sección y tiene que ser estable: si cambia, el usuario
 * pierde lo que había elegido.
 */
export function useSeccionAbierta(clave: string, porDefecto = false) {
  const abierto = useSyncExternalStore(
    suscribir,
    // El snapshot devuelve un booleano, que se compara por valor: no hay
    // bucle de renders como pasaría devolviendo un objeto nuevo cada vez.
    () => leerEstado()[clave] ?? porDefecto,
    // En el servidor no hay almacenamiento: se dibuja el valor por defecto y
    // React reconcilia después de hidratar.
    () => porDefecto,
  );

  const alternar = useCallback(() => {
    const estado = leerEstado();
    guardarEstado({ ...estado, [clave]: !(estado[clave] ?? porDefecto) });
  }, [clave, porDefecto]);

  return { abierto, alternar };
}


/** Vacía la memoria del módulo. Sólo para los tests: sin esto, el primer test
 *  que lee deja la caché puesta y los siguientes no ven el almacenamiento. */
export function _olvidarCache() {
  memoria = null;
}

import "server-only";

import { cache } from "react";
import { cookies } from "next/headers";

import {
  AUTH_COOKIE_NAME,
  isRole,
  isUserType,
  type Role,
  type SessionUser,
} from "@/lib/auth-types";

const BACKEND =
  process.env.BACKEND_API_URL ??
  process.env.NEXT_PUBLIC_API_URL ??
  "http://localhost:8000";

export async function getServerToken(): Promise<string | null> {
  return (await cookies()).get(AUTH_COOKIE_NAME)?.value ?? null;
}

/** Verify the browser token with the Backend, which remains the auth authority. */
export const getVerifiedSession = cache(async (): Promise<SessionUser | null> => {
  const token = await getServerToken();
  if (!token) return null;

  try {
    const response = await fetch(`${BACKEND}/auth/me`, {
      cache: "no-store",
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) return null;

    const payload = (await response.json()) as Partial<SessionUser> & {
      user_type?: unknown;
    };
    if (typeof payload.username !== "string" || !isRole(payload.role)) return null;
    return {
      username: payload.username,
      role: payload.role,
      userType: isUserType(payload.user_type) ? payload.user_type : null,
    };
  } catch {
    return null;
  }
});

export async function getServerRole(): Promise<Role> {
  return (await getVerifiedSession())?.role ?? "user";
}

import "server-only";

import { cookies } from "next/headers";

import { getVerifiedSession } from "@/lib/server-auth";
import { profileIdForUserType } from "@/lib/auth-types";

export type ProfileId = "airline" | "passenger";

const COOKIE = "ontimeai-profile";

/**
 * El perfil con el que hay que dibujar la página, resuelto en el servidor.
 *
 * Mismo orden de precedencia que `ProfileProvider` en el cliente: el override
 * local manda, y si no hay, el perfil de la cuenta. Las dos piezas tienen que
 * coincidir o la misma pantalla termina con el menú de un perfil y el
 * contenido del otro.
 *
 * Por eso el override es una cookie: `localStorage` no llega hasta acá.
 */
export async function getServerProfile(): Promise<ProfileId> {
  const session = await getVerifiedSession();
  const puedeElegir = session?.role === "admin" || session?.role === "superadmin";

  if (puedeElegir) {
    const guardado = (await cookies()).get(COOKIE)?.value;
    if (guardado === "airline" || guardado === "passenger") return guardado;
  }

  return session?.userType ? profileIdForUserType(session.userType) : "passenger";
}

/**
 * Traducción de features del modelo a lenguaje natural (issue #7).
 *
 * El booster v9 expone 84 features con nombres de código (`TAIL_DELAY_DECAY`,
 * `dest_delay_rate_24h`, `ORIG_WX_SKNT`). Mostrarlos en crudo obliga al lector
 * a conocer el feature engineering. Acá se traducen a un nombre corto y a una
 * frase que además depende de la dirección del aporte SHAP: la misma variable
 * explica algo distinto según empuje el riesgo hacia arriba o hacia abajo.
 */

export type FactorCopy = {
  /** Nombre corto, apto para una tabla. */
  title: string;
  /** Frase cuando el factor aumenta el riesgo. */
  up: string;
  /** Frase cuando el factor lo reduce. */
  down: string;
};

/** Métricas meteorológicas: aplican igual a origen y destino. */
const WX_METRICS: Record<string, FactorCopy> = {
  TMPC: {
    title: "Temperatura",
    up: "La temperatura {loc} acompaña condiciones que suelen demorar la operación",
    down: "La temperatura {loc} está en un rango sin impacto operativo",
  },
  DWPC: {
    title: "Punto de rocío",
    up: "El punto de rocío {loc} indica humedad alta, asociada a niebla o tormentas",
    down: "El punto de rocío {loc} no sugiere formación de niebla",
  },
