const AWC_URL = "https://aviationweather.gov/api/data/metar";

export class WeatherApiError extends Error {
  constructor(
    message: string,
    public readonly cause?: unknown,
  ) {
    super(message);
    this.name = "WeatherApiError";
  }
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
export async function fetchMetars(
  ids: string[],
  { revalidate = 300 }: { revalidate?: number } = {},
): Promise<AwcMetar[]> {
  const url = new URL(AWC_URL);
  url.searchParams.set("ids", ids.join(","));
  url.searchParams.set("format", "json");
  url.searchParams.set("taf", "false");

  const started = Date.now();
  console.log(`\n[AWC] → GET ${url.toString()}`);

  let res: Response;
  try {
    res = await fetch(url, {
      headers: { Accept: "application/json" },
      next: { revalidate },
    });
  } catch (e) {
    console.error(`[AWC] ✖ network error after ${Date.now() - started}ms`, e);
    throw new WeatherApiError(
      `No se pudo contactar Aviation Weather Center (${
        e instanceof Error ? e.message : "network error"
      })`,
      e,
    );
  }

  const ms = Date.now() - started;
  console.log(
    `[AWC] ← ${res.status} ${res.statusText} in ${ms}ms (cache: ${
      res.headers.get("x-vercel-cache") ?? res.headers.get("cf-cache-status") ?? "n/a"
    })`,
  );

  if (!res.ok) {
    throw new WeatherApiError(
      `AWC devolvió ${res.status} ${res.statusText}`,
    );
  }

  let data: unknown;
  try {
    data = await res.json();
  } catch (e) {
    throw new WeatherApiError("Respuesta de AWC no es JSON válido", e);
  }

  if (!Array.isArray(data)) {
    throw new WeatherApiError(
      "Respuesta inesperada de AWC: se esperaba un array",
    );
  }

  console.log(
    `[AWC] ✓ ${data.length} estaciones recibidas · ejemplo KATL:`,
    JSON.stringify(
      (data as AwcMetar[]).find((m) => m.icaoId === "KATL") ?? data[0],
      null,
      2,
    ),
  );

  if (data.length === 0) {
    throw new WeatherApiError(
      "AWC devolvió cero estaciones — verificá los códigos ICAO",
    );
  }

  return data as AwcMetar[];
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
function parseVisibility(v: string | number | null): number | null {
  if (v == null) return null;
  if (typeof v === "number") return v;
  const trimmed = v.trim();
  if (trimmed.endsWith("+")) {
    const n = parseFloat(trimmed.slice(0, -1));
    return Number.isFinite(n) ? n : null;
  }
  if (trimmed.includes("/")) {
    let total = 0;
    for (const part of trimmed.split(/\s+/)) {
      if (part.includes("/")) {
        const [num, den] = part.split("/").map(Number);
        if (den) total += num / den;
      } else {
        total += Number(part) || 0;
      }
    }
    return total || null;
  }
  const n = parseFloat(trimmed);
  return Number.isFinite(n) ? n : null;
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
function deriveCondition(m: AwcMetar): WeatherStation["condition"] {
  const wx = (m.wxString ?? "").toUpperCase();
  if (/TS|SQ/.test(wx)) return "storm";
  if (/FG|FZFG|BR/.test(wx)) return "fog";
  if (/RA|DZ|SH|PL/.test(wx)) return "rain";
  if (/SN/.test(wx)) return "rain";

  const vis = parseVisibility(m.visib);
  if (vis !== null && vis < 3) return "fog";

  const clouds = m.clouds ?? [];
  const hasOvc = clouds.some((c) => c.cover === "OVC");
  const hasBkn = clouds.some((c) => c.cover === "BKN");
  if (hasOvc || hasBkn) return "cloudy";

  return "clear";
}

// eslint-disable-next-line complexity -- deuda registrada en .complejidad-baseline.json
function deriveImpact(m: AwcMetar): WeatherStation["impact"] {
  const cat = m.fltCat;
  if (cat === "LIFR" || cat === "IFR") return "high";
  if (cat === "MVFR") return "medium";

  const vis = parseVisibility(m.visib);
  const wind = m.wspd ?? 0;
  const gust = m.wgst ?? 0;
  const wx = (m.wxString ?? "").toUpperCase();

  if (/TS|SQ/.test(wx) || (vis !== null && vis < 1) || wind > 25 || gust > 30) return "high";
  if (/RA|SN|FG|BR/.test(wx) || (vis !== null && vis < 5) || wind > 15) return "medium";
  return "low";
}

function cleanStationName(raw: string | undefined, icao: string): string {
  if (!raw) return icao;
  const firstChunk = raw.split(",")[0]?.trim() ?? raw;
  return firstChunk.replace(/\/.*$/, "").trim() || icao;
}

export function metarToStation(m: AwcMetar): WeatherStation {
  const tempF = m.temp != null ? Math.round((m.temp * 9) / 5 + 32) : null;
  const parsedVisibility = parseVisibility(m.visib);

  return {
    code: m.icaoId.replace(/^K/, ""),
    name: cleanStationName(m.name, m.icaoId),
    lat: m.lat,
    lng: m.lon,
    temperatureF: tempF,
    windKt: m.wspd == null ? null : Math.round(m.wspd),
    windDeg: m.wdir,
    visibilitySm: parsedVisibility == null ? null : Math.round(parsedVisibility),
    condition: deriveCondition(m),
    impact: deriveImpact(m),
  };
}

export async function fetchWeatherStations(
  ids: string[] = ATL_REGIONAL_STATIONS,
): Promise<{
  stations: WeatherStation[];
  atlRaw: string | null;
  fetchedAt: string;
  requestUrl: string;
  rawPayload: AwcMetar[];
}> {
  const requestUrl = `${AWC_URL}?ids=${ids.join(",")}&format=json&taf=false`;
  const metars = await fetchMetars(ids);
  const stations = metars.map(metarToStation);
  const atl = metars.find((m) => m.icaoId === "KATL");
  return {
    stations,
    atlRaw: atl?.rawOb ?? null,
    fetchedAt: new Date().toISOString(),
    requestUrl,
    rawPayload: metars,
  };
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { AUTH_COOKIE_NAME, AUTH_MAX_AGE_SECONDS } from "@/lib/auth-types";

/**
 * Rutas accesibles con o sin sesión. El resto de la app es Modo Pro y exige
 * autenticación.
 *
 * - `/live`: Modo Lite, vista pública de solo lectura (issue #1).
 * - `/privacidad` y `/soporte`: las dos tiendas exigen que abran sin login, y
 *   Apple lo verifica antes de aceptar el envío a revisión.
 */
const PUBLIC_ROUTES = ["/privacidad", "/soporte"];

function hardenCookie(response: NextResponse, token: string | undefined) {
  if (!token) return response;
  response.cookies.set(AUTH_COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    maxAge: AUTH_MAX_AGE_SECONDS,
    path: "/",
    priority: "high",
  });
  return response;
}

export function proxy(request: NextRequest) {
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;
  const { pathname } = request.nextUrl;

  // Modo Lite: no exige sesión. Si el visitante la tiene, se le renueva igual.
  const isPublic = PUBLIC_ROUTES.some(
    (route) => pathname === route || pathname.startsWith(`${route}/`),
  );
  if (isPublic) {
    return hardenCookie(NextResponse.next(), token);
  }

  // Login y alta: accesibles sin sesión, y sin sentido con una. Quien ya entró
  // y vuelve acá —por un enlace viejo, por el botón de atrás— va al inicio en
  // vez de ver un formulario que no necesita.
  if (pathname === "/login" || pathname === "/signup") {
    if (token) {
      return hardenCookie(
        NextResponse.redirect(new URL("/", request.url)),
        token,
      );
    }
    return NextResponse.next();
  }

  if (!token) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("from", pathname);
    return NextResponse.redirect(loginUrl);
  }

  return hardenCookie(NextResponse.next(), token);
}

export const config = {
  // Se excluyen rutas de API (una redirección rompería los fetch del BFF),
  // assets de Next y cualquier archivo con extensión — estos últimos para que
  // el favicon y las imágenes carguen en /live sin sesión.
  matcher: ["/((?!api/|_next/static|_next/image|.*\\.).*)"],
};
